/* 論語選—子路曾皙冉有公西華侍坐 */
(window.TB_LESSONS = window.TB_LESSONS || []).push(["論語選—子路曾皙冉有公西華侍坐", {"title": "論語選—子路曾皙冉有公西華侍坐", "textPages": [{"seg": "第一段", "title": "第一段", "book": "課本 P.100", "noteStart": 1, "sub": "孔子問志——師生相處氣象", "pian": "孔子問志——師生相處氣象，凸顯孔子和藹可親、循循善誘的長者風範。", "xi": "以「言志」貫串全文。「侍坐」二字摹寫現場，用詞簡約，與孔子平易親切的問話相配合，當時情景可見一斑。", "fan": "子路、曾皙、冉有、公西華陪孔子坐著。孔子說：「不要因為我的年紀比你們稍大，就不好意思說出自己的志向。平日你們總是說：『沒有人了解我！』如果有人了解你們，那你們用什麼來表現自己的才能？」", "lines": [{"text": "{n:1|子路}、{n:2|曾皙}、{n:3|冉有}、{n:4|公西華}{g:侍坐|陪孔子坐著。「侍」字暗示有長輩在座，由下句知為孔子}。", "tr": "子路、曾皙、冉有、公西華陪孔子坐著。", "cite": "侍坐", "mean": "弟子們依長幼次序侍坐於孔子身旁，表現出師生間日常的輕鬆和諧。"}, {"text": "子曰：「{n:5|以吾一日長乎爾}，{n:6|毋吾以也}。", "tr": "孔子說：「不要因為我的年紀比你們稍大，就不好意思說出自己的志向。", "mean": "孔子刻意以『年長』自謙、以『平日抱怨無人知』為引，其真正用意是解除弟子尊卑長幼的顧慮，營造敢於言志的氣氛。", "cite": "以吾一日長乎爾", "rhet": [["倒裝", "<span class=\"tp-rq\">一日長乎爾</span>──即「長乎爾一日」。"], ["省略", "<span class=\"tp-rq\">毋吾以也</span>──即「毋以吾長於爾而不敢言」。"], ["倒裝", "<span class=\"tp-rq\">毋吾以也</span>──即「毋以吾也」。"]], "meanShort": "孔子以和藹的措辭與態度，解除弟子尊卑長幼的顧慮，開啟各自言志的良好氣氛", "rhetShort": ["以吾長乎爾一日", null, "毋以吾也"]}, {"text":"{n:7|居}則曰：『不吾知也！』如{g:或|有人}知爾，{n:8|則何以哉}？」","tr":"平日你們總是說：『沒有人了解我！』如果有人了解你們，那你們用什麼來表現自己的才能？」","rcite":["不吾知也"],"rhet":[["倒裝","<span class=\"tp-rq\">不吾知也</span>──否定句代詞賓語前置，即『不知吾也』；『毋吾以也』（＝毋以吾也）、『則何以哉』（＝則以何哉）亦同。"],["倒裝","<span class=\"tp-rq\">則何以哉</span>──即『則以何哉』。"]],"rhetShort":["不知吾也","則以何哉"],"ask":["<div class=\"gd gd-one\" data-gq=\"op\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">開場</span>孔子問「如或知爾，則何以哉」，是在問什麼？<div class=\"gd-qa\">如果有人了解你、願意任用你，你要怎麼做？</div></div></div>"],"askT":"朱熹注：「言女平居，則言人不知我。如或有人知女，則女將何以為用也？」"}], "qa": [["孔子說：「以吾一日長乎爾，毋吾以也！」這句話的意思是要學生：<br>□1.不要因為老師在場就不敢講出真心話來<br>□2.不要因為老師年長就不好意思說出志向<br>□3.不要因為老師年長就不好意思提出批判", "2.不要因為老師年長就不好意思說出志向"], ["孔子詢問各人志向，為何一開始說『以吾一日長乎爾，毋吾以也』？", "去除學生的戒慎恐懼，緩和現場氣氛，如此學生才會說出內心真正的想法。"]], "notes": [["子路", "姓仲名由，字子路，一字季路，魯國人，率直好勇，擅長政事，小孔子九歲。"], ["曾皙", "姓曾名點，字皙（ㄒㄧ），魯國人，放浪灑脫，小孔子二十餘歲，與兒子曾參同為孔子弟子。"], ["冉有", "姓冉名求，字子有，魯國人，謙和多才藝，擅長政事，小孔子二十九歲。"], ["公西華", "姓公西名赤，字子華，魯國人，熟習禮儀，擅長外交，小孔子四十二歲。"], ["以吾一日長乎爾", "因為我的年紀比你們稍長。以，因為。一日長乎爾，即『長乎爾一日』的倒裝。長，ㄓㄤˇ。"], ["毋吾以也", "即『毋以吾也』。不要因為我年長而不好意思說話。"], ["居", "平日。"], ["則何以哉", "即『則以何哉』。那麼你們用什麼來表現自己的才能？以，用。"]]}, {"seg": "第二段", "title": "第二段", "book": "課本 P.101", "noteStart": 9, "sub": "弟子述志——子路", "pian": "弟子述志——子路，率爾而對（軍事、禮義）。", "xi": "子路率爾回答，個性衝動、自負；孔子『哂之』褒貶寓含其中，不助長其驕矜之氣，顯示為師者因材施教的細膩。", "fan": "子路不加思索地搶先答道：「一個擁有一千輛兵車的國家，夾處在大國之間，又受到外敵侵略，接著又鬧饑荒，讓我來治理，等到三年，可使人民有勇氣，並且懂得禮義。」孔子微微一笑。", "lines": [{"text":"子路{n:9|率爾}而{g:對|回答地位高的人的問題或接續他們的話}曰：「{n:10|千乘之國}，{n:11|攝}乎大國之間，{n:12|加之以師旅}，{n:13|因之以饑饉}。","tr":"子路不加思索地搶先答道：「一個擁有一千輛兵車的國家，夾處在大國之間，又受到外敵侵略，接著又鬧饑荒，","rcite":["師旅"],"rhet":[["借代","<span class=\"tp-rq\">師旅</span>──以『師旅（軍隊）』借代『戰爭』。"]],"cite":"率爾而對","mean":"顯露其粗豪、好勇的性格。","rhetShort":["戰爭"],"ask":["<div class=\"gd gd-one\" data-gq=\"s1\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">①</span>子路的國家遇到什麼困難？<div class=\"gd-qa\">夾在大國之間，又有戰爭、饑荒：內憂外患。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>攝＝夾處；加之以師旅＝又受到外敵的侵略（課本註）；饑饉＝荒年；千乘之國；一個內憂外患的國家</div><div class=\"tk-sep\"></div>朱熹注：「穀不熟曰饑，菜不熟曰饉。」"}, {"text":"{n:14|由}也{z:為|ㄨㄟˊ，治理}之，{n:15|比及}三年，可使有勇，且知{n:16|方}也。」","tr":"讓我來治理，等到三年，可使人民有勇氣，並且懂得禮義。」","cite":"比及三年，可使有勇，且知方也","mean":"子路自言必能使人民有勇且知義，反映出子路的自信與直率。<span class='tm-sup'>孔子曾曰：「由也，千乘之國，可使治其賦（軍事）也。」</span>","ask":["<div class=\"gd gd-one\" data-gq=\"s2\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">②</span>子路想在三年內做到什麼？<div class=\"gd-qa\">使人民有勇氣，也懂得禮義（知方）。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>由＝子路自稱；比及＝等到；方＝禮義；「可使有勇，且知方也」</div>"}, {"text":"夫子{n:17|哂}之。","tr":"孔子微微一笑。","mean":"子路以極不利的處境反襯自己三年治國之效，凸顯其自信直率；而「哂之」顯示孔子對其「不讓」有所保留。孔子深知子路喜歡追求英雄式的成功，卻又誇言禮義（方），故未讚許子路，這個笑一方面是肯定其志向，一方面是覺得其不夠禮讓，故不多加評論，以笑提醒他勿躁進，顯示出為師者因材施教的細膩。","cite":"夫子哂之","meanShort":"「哂」既肯定子路之志，也以微笑提醒他不夠禮讓、勿躁進","ask":["<div class=\"gd gd-one\" data-gq=\"s3\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">③</span>孔子為什麼「哂」子路？先猜猜。<div class=\"gd-qa\">先記下你的猜測，第六段孔子會自己說。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>哂＝微笑；率爾＝輕率、搶先；原因在第六段「為國以禮，其言不讓」</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>孔子當下可能有什麼情緒</div><div class=\"tk-sep\"></div>孔子當場只笑不說破，是點到為止的提醒。"}], "qa": [["『子路率爾而對曰』可看出子路的性格是？", "率直、衝動（粗豪好勇）。"], ["子路的回應內容何處表現對自己能力的自信？", "以『千乘之國、夾處大國、外敵侵略、饑饉』的極不利條件，對比『三年、有勇、知方』的高成就，足見其自信。"]], "notes": [["率爾", "輕率的樣子，此有搶先之意。"], ["千乘之國", "擁有一千輛兵車的國家。乘（ㄕㄥˋ），古代計算車輛的單位，此指兵車。春秋時代常以兵車數量表示國家的大小與實力。"], ["攝", "ㄕㄜˋ，夾處。"], ["加之以師旅", "又受到外敵的侵略。加，加上。師旅，軍隊。<span class='tm-sup'>朱熹注：「二千五百人為師，五百人為旅。」</span>"], ["因之以饑饉", "接著又鬧饑荒。因，接連。饑（ㄐㄧ）饉（ㄐㄧㄣˇ），荒年。"], ["由", "子路自稱。古代禮俗，自稱或稱呼晚輩時以名，尊稱他人時則以字。"], ["比及", "等到。『比』和『及』同義。比，ㄅㄧˋ。<span class='tm-sup'>【102學測】考過「比」及三年＝等到。</span>"], ["方", "此指禮義。<span class='tm-sup'>朱熹注：「方，向也，謂向義也。」所以課本注為「禮義」。</span>"], ["哂", "ㄕㄣˇ，微笑。"]], "askLabel": "本段統整", "ask": ["<div class=\"gd gd-sum\" data-gq=\"sum2\"><div class=\"gd-q\">子路的回答</div><div class=\"gd-board vis\" onclick=\"gdTap(this)\"><span class=\"gd-bh\">子路的回答：問題 → 方法 → 結果</span><div class=\"gd-bt\"><div>問題：<b>大國壓迫、戰爭（師旅）、饑荒（饑饉）</b></div><div class=\"gd-bar\">↓</div><div>方法：<b>由也為之</b>，比及三年</div><div class=\"gd-bar\">↓</div><div>結果：<b>可使有勇，且知方也</b></div></div></div></div>"], "askT": "<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>子路的回答：問題（內憂外患）→ 方法（由也為之，比及三年）→ 結果（有勇、知方）</div>"}, {"seg": "第三段", "title": "第三段", "book": "課本 P.101–102", "noteStart": 18, "sub": "弟子述志——冉有", "pian": "弟子述志——冉有，問而後答（經濟、民生）。", "xi": "與子路自詡能做到禮義教化相較，冉有卻表示須待更賢能的君子才能實行禮樂，呈現冉有『退』與『讓』的個性。", "fan": "「求，你怎樣呢？」冉有回答：「一個六、七十里或五、六十里見方的小國，讓我治理，三年後可使人民富足。至於禮樂教化，就只有等待更有才德的君子了。」", "lines": [{"text": "「求，爾何如？」", "tr": "「求，你怎樣呢？」", "rhet": [["倒裝", "<span class=\"tp-rq\">爾何如</span>──即「爾如何」；後文「赤，爾何如」「點，爾何如」同。"]], "rhetShort": ["爾如何"]}, {"text":"對曰：「{n:18|方六、七十}，{n:19|如}五、六十，求也為之，比及三年，可{n:20|使足民}。","tr":"冉有回答：「一個六、七十里或五、六十里見方的小國，讓我治理，三年後可使人民富足。","rcite":["可使足民"],"rhet":[["倒裝","<span class=\"tp-rq\">可使足民</span>──即『可使民足』的倒裝。"]],"cite":"方六、七十，如五、六十","mean":"越說越小，反映冉有的謙退保守。","cite2":"比及三年，可使足民","mean2":"<span class='tm-sup'>孔子曾曰：「求也，千室之邑，百乘之家，可使為之宰也。」</span>","rhetShort":["可使民足"],"ask":["<div class=\"gd gd-one\" data-gq=\"s4\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">④</span>冉有和子路，哪裡不同？<div class=\"gd-qa\">治理的國家較小；目標是使人民富足。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>方六、七十＝每邊長六、七十里的土地，此指小國（課本註；「方圓」是常見說法，依課本）；如＝或者；足民＝使人民富足</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>冉有是否刻意謙退（朱熹：謙退，又見子路被哂）</div><div class=\"tk-sep\"></div>朱熹注：「冉有謙退，又以子路見哂，故其辭益遜。」<br>延伸：開頭敘述稱「子路、曾皙、冉有、公西華」（字，表示尊重），孔子問話卻直呼「求」「赤」「點」（名，長輩稱晚輩）。"}, {"text":"{n:21|如}其禮樂，{g:以|則、就}{n:22|俟}君子。」","tr":"至於禮樂教化，就只有等待更有才德的君子了。」","mean":"冉有先言小國、再言僅能『足民』、又把禮樂讓與君子，句句退讓，與子路的『率爾』形成對比，見其謙遜保守。","cite":"如其禮樂，以俟君子","meanShort":"冉有句句退讓，可見其謙遜保守，與子路形成對比。","ask":["<div class=\"gd gd-one\" data-gq=\"s5\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑤</span>禮樂，冉有交給誰？<div class=\"gd-qa\">交給君子推行；他自己負責使人民富足。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>如＝至於；俟＝等待；禮樂「以俟君子」（朱熹：言非己所能）</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>冉有怎樣界定自己的能力</div><div class=\"tk-sep\"></div>朱熹注：「俟君子，言非己所能。」<br>〈子路〉原文：子適衛，冉有僕。子曰：「庶矣哉！」冉有曰：「既庶矣，又何加焉？」曰：「富之。」曰：「既富矣，又何加焉？」曰：「教之。」"}], "qa": [], "notes": [["方六、七十", "每邊長六、七十里的土地面積，此指小國。方，計算面積的用語。"], ["如", "或者。下文『如會同』的『如』義同。"], ["使足民", "讓人民富足。（『足民』即『民足』的倒裝）"], ["如", "至於。"], ["俟", "ㄙˋ，等待。"]]}, {"seg": "第四段", "title": "第四段", "book": "課本 P.102", "noteStart": 23, "sub": "弟子述志——公西華", "pian": "弟子述志——公西華，問而後答（外交）。", "xi": "孔子一一垂問弟子，聆聽而不評論，為之後與曾皙的對話埋下伏筆；未在一開始即催促最小的公西華發言，也顯示孔子因材施教的細膩安排。", "fan": "「赤，你怎樣呢？」公西華回答：「不敢說能做好，只希望能有學習的機會。在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服、戴著禮帽，做個贊禮的小相。」", "lines": [{"text": "「赤，爾何如？」", "tr": "「赤，你怎樣呢？」"}, {"text":"對曰：「非曰能之，願學焉。","tr":"公西華回答：「不敢說能做好，只希望能有學習的機會。","mean":"公西華以『非曰能之，願學焉』一字之退，較冉有更為謙抑；所志雖為宗廟會同的外交大事，卻自居『小相』。<br>公西華年紀最小，「能」與「學」一字之改，更見謙遜。","cite":"非曰能之，願學焉","meanShort":"公西華年紀最小，『能』與『學』一字之改，更見謙遜","ask":["<div class=\"gd gd-one\" data-gq=\"s6\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑥</span>「非曰能之，願學焉」是什麼態度？<div class=\"gd-qa\">不說自己已經能做到，而是說願意學習。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>「非曰能之，願學焉」；宗廟之事＝諸侯祭祖大典；會同＝朝覲、會盟</div><div class=\"tk-sep\"></div>朱熹注：「公西華志於禮樂之事，嫌以君子自居。故將言己志而先為遜辭，言未能而願學也。」"}, {"text":"{n:23|宗廟之事}，如{n:24|會同}，{n:25|端章甫}，願{z:為|ㄨㄟˊ}{n:26|小相}焉。」","tr":"在諸侯祭祀或朝覲、會盟的典禮上，我願意穿著禮服、戴著禮帽，做個贊禮的小相。」","cite":"宗廟之事，如會同，端章甫，願為小相焉","mean":"<span class='tm-sup'>孔子曾曰：「赤也，束帶立於朝，可使與賓客言也。」</span>","rhet":[["轉品","<span class=\"tp-rq\">端章甫</span>──「端」（禮服）、「章甫」（禮帽）本為名詞，此作動詞「穿禮服、戴禮帽」（名→動）。"]],"rhetShort":["名→動"],"ask":["<div class=\"gd gd-one\" data-gq=\"s7\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑦</span>公西華想做什麼？<div class=\"gd-qa\">在宗廟祭祀、諸侯會同的典禮中擔任小相（協助引導、贊禮）。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>端章甫＝穿禮服、戴禮帽（名詞作動詞）；小相＝贊禮者，「小」是謙詞</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>公西華是否有更大的能力（第六段揭曉）</div><div class=\"tk-sep\"></div>延伸：若以現代職位類比，子路如國防部長、冉有如財經首長、公西華如外交部長；A卷選擇第 24 題考過依專長指派內閣職務（曾皙不適合）。"}], "qa": [["公西華熱衷宗廟祭祀與諸侯朝覲、會盟，最適合的工作部門是？", "外交部。"], ["從冉有、公西華的回答中，哪些地方看出他們謙退？", "冉有僅能使小國人民富足、禮樂待君子；公西華不敢言『能』，僅願學、做小相。"]], "notes": [["宗廟之事", "此指諸侯祭祀祖先的大典。"], ["會同", "指諸侯朝覲天子或諸侯會盟之事。"], ["端章甫", "穿著禮服，戴著禮帽。端，玄端，古代禮服。章甫（ㄈㄨˇ），玄冠，古代禮帽。此皆作動詞。"], ["小相", "ㄒㄧㄤˋ，典禮中擔任司儀或贊禮（輔佐禮儀進行）的人。小，謙詞。"]], "askLabel": "本段統整", "ask": ["<div class=\"gd gd-one\" data-gq=\"s8\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑧</span>三人怎麼說自己的能力？<div class=\"gd-qa\">子路直接承擔（由也為之）；冉有限定範圍（求也為之、以俟君子）；公西華說願學、自稱小相。</div></div><table class=\"ly-table\"><thead><tr><th></th><th>子路</th><th>冉有</th><th>公西華</th></tr></thead><tbody><tr><th>想為國家做什麼</th><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>使人民有勇、知方</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>使人民富足</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>參與宗廟、會同的禮儀</span></span></td></tr><tr><th>開口怎麼說</th><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>由也為之</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>求也為之</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>非曰能之，願學焉</span></span></td></tr></tbody></table></div>"], "askT": "<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>三人都在回答「如或知爾，則何以哉」：有勇知方／足民／宗廟會同願為小相</div><div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>子路「率爾而對」「由也為之」；冉有「求也為之」「以俟君子」；公西華「非曰能之，願學焉」「願為小相」</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>三人的個性怎麼形容</div><div class=\"tk-sep\"></div>段析：孔子一一垂問，聆聽而不評論，為之後與曾皙的對話埋下伏筆。"}, {"seg": "第五段", "title": "第五段", "book": "課本 P.102–103", "noteStart": 27, "sub": "弟子述志——曾皙（禮樂融合）", "pian": "弟子述志——曾皙，孔子問、止瑟而答（禮樂融合）。", "xi": "曾皙所描繪的是禮樂治理下太平社會的縮影，與孔子『風清俗美、人民安樂』的政治理想相符，故深獲嘉許（此說以朱熹為代表）。『鼓瑟希』使讀者恍然大悟，原來對話從一開始便在音樂聲中進行。", "fan": "「點，你怎樣呢？」曾皙正鼓瑟，瑟聲漸歇，鏗然一聲，放下瑟站起來，答：「我和他們三位所講的不同。」孔子：「有什麼關係呢？不過各自談談志向罷了。」曾皙：「晚春時節，穿上做好的春裝，與五、六個成年人、六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」孔子嘆息：「我贊同點所說的呀！」", "lines": [{"text": "「點，爾何如？」", "tr": "「點，你怎樣呢？」"}, {"text":"{n:27|鼓瑟希}，{n:28|鏗爾}，{n:29|舍瑟而作}，對曰：「異乎三子者之{n:30|撰}。」","tr":"曾皙正鼓瑟，瑟聲漸歇，鏗然一聲，放下瑟站起來，答：「我和他們三位所講的不同。」","cite":"鼓瑟希","mean":"此時才問年紀第二大的曾皙，「鼓瑟希」使讀者恍然大悟，原來這場對話從一開始便是在音樂聲中進行的。","cite2":"舍瑟而作","mean2":"曾皙以閒雅的態度結束彈瑟，「作」這個起身的動作，將曾皙的恭敬之態刻劃得極傳神。","rhet":[["轉品","<span class=\"tp-rq\"><b class='rq-hi'>鼓</b>瑟希</span>──『鼓』本為名詞，此作動詞（名→動）。"]],"rhetShort":["名→動"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>鼓瑟希（希＝稀）；鏗爾；舍瑟而作（作＝起立）</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>從動作推論曾皙從容有禮（推論，不是課文明寫）</div><div class=\"tk-sep\"></div>朱熹注：「四子侍坐，以齒為序，則點當次對。以方鼓瑟，故孔子先問求、赤而後及點也。」——曾皙年紀排第二，因為正在彈瑟，最後才被問到。<br>「鼓瑟希」也讓讀者發現：原來整場對話都在樂聲中進行。","ask":["<div class=\"gd gd-one\" data-gq=\"s9\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑨</span>曾皙和子路，回答前的動作哪裡不同？<div class=\"gd-qa\">子路搶先回答；曾皙停下彈瑟、放下瑟、起身才回答。</div></div><div class=\"gd-board vis\" onclick=\"gdTap(this)\"><span class=\"gd-bh\">同樣是回答孔子</span><div class=\"gd-bt\"><div class=\"gd-bcols\"><div>子路</div><div>曾皙</div></div><div class=\"gd-bcols\"><div><b>率爾而對</b></div><div><b>鼓瑟希，鏗爾，舍瑟而作</b></div></div><div class=\"gd-bcols\"><div>搶先回答</div><div>停下、起身才回答（推論：從容有禮）</div></div></div></div></div>"]}, {"text":"子曰：「何{n:31|傷}乎？{g:亦|只是}各言其志也。」","tr":"孔子：「有什麼關係呢？不過各自談談志向罷了。」","rcite":["何傷乎"],"rhet":[["激問","<span class=\"tp-rq\">何傷乎</span>──明知故問以寬解曾皙，答案即在問中。"]],"rhetShort":["明知故問以寬解曾皙"],"ask":["<div class=\"gd gd-one\" data-gq=\"s10\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑩</span>曾皙說「異乎三子者之撰」，孔子怎麼回應？<div class=\"gd-qa\">「何傷乎？亦各言其志也」：說說無妨，本來就是各說各的志向。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>撰＝陳述（課本註）；何傷乎＝有什麼妨礙；「亦各言其志也」</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>—（另一說：朱熹、《論語注疏》「撰，具也」，只在「師」）</div><div class=\"tk-sep\"></div>「撰」：課本註「此指陳述」。朱熹《集注》、《論語注疏》作「撰，具也」，指所具備的才能——注本不同，課堂以課本為準。"}, {"text":"曰：「{n:32|莫春}者，{g:春服|有襯裡但內無填裝棉絮的上衣，只在春天穿}既成，{n:33|冠者}五、六人，童子六、七人，{n:34|浴乎沂}，{n:35|風乎舞雩}，詠而歸。」","tr":"曾皙：「晚春時節，穿上做好的春裝，與五、六個成年人、六、七個孩童，到沂水邊洗洗澡，在求雨的祭壇上吹風乘涼，然後唱著歌回家。」","rcite":["風乎舞雩"],"rhet":[["轉品","<span class=\"tp-rq\">風乎舞雩</span>──『風』本為名詞，此作動詞『吹風乘涼』（名→動）。"],["借代","<span class=\"tp-rq\">冠者</span>──以「冠」（二十歲行加冠禮）借代成年，冠者即成年男子。"]],"cite":"莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸","mean":"曾皙胸次悠然，從容體道，所描述自在和樂的生活景象，展現與萬物交感的襟懷。","rhetShort":["名→動","成年男子"],"ask":["<div class=\"gd gd-one\" data-gq=\"s11\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑪</span>曾皙描繪的是什麼畫面？<div class=\"gd-qa\">暮春時節，大人和孩子一起到沂水邊洗浴、在舞雩臺上乘涼，唱著歌回家。</div></div></div>","<div class=\"gd gd-one\" data-gq=\"s12\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑫</span>曾皙沒有談治國，為什麼也算「志」？<div class=\"gd-qa\">他說的是自己嚮往的生活；志向也可以是想過的生活，不一定是官職。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>莫春＝晚春；冠者＝成年男子；浴乎沂、風乎舞雩（舞雩＝求雨的祭壇）、詠而歸</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>畫面給人的感受</div><div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>曾皙描繪嚮往的生活，孔子贊同其志（課本段析：禮樂治理下太平社會的縮影）</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>曾皙是否以百姓為念</div><div class=\"tk-sep\"></div>曾皙的畫面可分成四層和諧：①莫春、春服既成——<b>人與天</b>；②冠者、童子同行——<b>己與群</b>；③浴乎沂、風乎舞雩——<b>人與境</b>；④詠而歸——<b>身心內在</b>。<br>課本採朱熹的說法：曾皙「即其所居之位，樂其日用之常」，「與天地萬物上下同流」。"}, {"text":"夫子{n:36|喟然}嘆曰：「吾{n:37|與}點也！」","tr":"孔子嘆息：「我贊同點所說的呀！」","mean":"曾皙不談治國之術，而以暮春出遊、浴沂風雩的和樂景象言志，展現禮樂教化下人與自然交融的太平氣象；孔子『喟然』而『與』，正因此境與其淑世理想相契。<br>「吾與點也」與孔子<span class='tm-sup'>「邦有道，則仕；邦無道，則可卷而懷之」（《論語．衛靈公》）</span>的思想相映。但「卷而懷之」非孔子初衷，故喟然長嘆。","cite":"吾與點也","meanShort":"曾皙之志契合孔子禮樂理想；「喟然」一嘆，是感嘆這太平之境不易實現","ask":["<div class=\"gd gd-one\" data-gq=\"s13\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑬</span>孔子為什麼說「吾與點也」？<div class=\"gd-qa\">贊同曾皙；寄寓對禮樂教化、清平盛世的期待（課本賞析）。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>喟然＝嘆息的樣子；與＝贊同；課本賞析：寄寓對禮樂教化、清平盛世的期待</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>「喟然嘆」是否也有理想難以實現的感慨</div><div class=\"tk-sep\"></div>也有一說認為：「吾與點也」與孔子「邦有道，則仕；邦無道，則可卷而懷之」（〈衛靈公〉）的思想相映；但「卷而懷之」並非孔子的初衷，所以喟然長嘆。<br>「亂世」：社會秩序混亂、諸侯彼此爭戰的時代。"}], "qa": [["孔子與弟子言志時，曾皙在一旁鼓瑟，你有何看法？", "（開放）一說為灑脫不羈、從容自在；一說依禮當停止動作恭敬回答，鼓瑟則近疏狂。請自由發揮。"], ["下列何者最可能是孔子『喟然稱許』曾皙的理由？", "孔子認同曾皙所嚮往的生活境界（禮樂治理下的太平氣象）。"]], "notes": [["鼓瑟希", "彈瑟聲音漸弱。鼓，彈奏。希，通『稀』。"], ["鏗爾", "ㄎㄥ，鏗的一聲，結束彈奏。鏗，狀聲詞。"], ["舍瑟而作", "放下瑟，站起來。舍（ㄕㄜˇ），通『捨』。作，起立。"], ["撰", "此指陳述。"], ["傷", "妨礙。"], ["莫春", "晚春，農曆三月。莫（ㄇㄨˋ），『暮』的本字。"], ["冠者", "ㄍㄨㄢˋ，成年男子。古代男子二十歲時舉行加冠禮，表示成年。<span class='tm-sup'>《禮記・曲禮上》：「二十曰弱，冠。」所以二十歲稱「弱冠」。</span>"], ["浴乎沂", "到沂（ㄧˊ）水邊洗浴。沂，河水名，在魯國都城曲阜南，源出山東省鄒城市。<span class='tm-sup'>【104學測】考過「沂」的字音。</span>"], ["風乎舞雩", "在求雨的祭壇上乘涼。風（此作動詞）。舞雩（ㄩˊ），古時求雨的祭壇；雩，求雨的祭典名稱。"], ["喟然", "ㄎㄨㄟˋ，嘆息的樣子。"], ["與", "贊同、讚許。"]], "askLabel": "本段統整", "ask": ["<div class=\"gd gd-sum\" data-gq=\"sum5\"><div class=\"gd-q\">前三子和曾皙，回答的切入點有什麼不同？</div><table class=\"ly-table\"><thead><tr><th></th><th>子路、冉有、公西華</th><th>曾皙</th></tr></thead><tbody><tr><th>說的是</th><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>受任後想承擔的政務</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>自己嚮往的生活情境</span></span></td></tr><tr><th>從哪裡切入</th><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>治理工作</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>生活景象</span></span></td></tr><tr><th>強調</th><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>如何做</span></span></td><td><span class='jy-blank' onclick=\"event.stopPropagation();this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>想過什麼樣的生活</span></span></td></tr></tbody></table><div class=\"gd-board vis\" onclick=\"gdTap(this)\"><span class=\"gd-bh\">「志」的兩種說法</span><div class=\"gd-bt\"><div class=\"gd-bcols\"><div>子路、冉有、公西華</div><div>曾皙</div></div><div class=\"gd-bcols\"><div>受任後要承擔的政務</div><div>嚮往的生活情境</div></div><div class=\"gd-bcols\"><div><b>怎麼做</b></div><div><b>想過什麼樣的生活</b></div></div><div class=\"gd-bar\">↓</div><div>這樣的生活，需要什麼樣的社會？（⑫）</div></div></div></div>"], "askT": "<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>前三子談受任後的政務；曾皙描繪嚮往的生活情境</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>曾皙說的是否就是「治理的目的」</div><div class=\"tk-sep\"></div>段析（朱熹說）：曾皙描繪禮樂治理下太平社會的縮影，與孔子的政治理想相符，故深獲嘉許。"}, {"seg": "第六段", "title": "第六段", "book": "課本 P.103–104", "noteStart": 38, "sub": "孔子評志——強調禮讓", "pian": "孔子評志——強調禮讓。", "xi": "孔子的回答均針對『其言不讓』說明『是故哂之』。全文以孔子具啟發性的問話開頭，又以其評語作結，『言志』二字貫穿全文，透過此線索表現『治國以禮』的思想，脈絡十分清楚。", "fan": "子路、冉有、公西華都出去了，曾皙留在後頭，問：「他們三位的話怎麼樣？」孔子：「也就是各自談談志向罷了。」曾皙：「老師為什麼笑由呢？」孔子：「治國應當講禮，子路的話毫不謙讓，所以我笑他。」曾皙：「求所說的，不是治國的事嗎？（不然老師怎麼都沒有表示？）」孔子：「怎麼見得六、七十里或五、六十里見方的地方，不算一個國家呢？（因為冉求很謙虛，所以我沒表示什麼，但他所說的，當然是屬於治理國家的事。）」曾皙：「赤所說的，不是治國的事嗎？（不然老師怎麼也沒有表示？）」孔子：「宗廟會同，不是諸侯的事又是什麼？公西華只能做小相，又有誰能做大相呢？」", "lines": [{"text": "三子者出，曾皙後。", "tr": "子路、冉有、公西華都出去了，曾皙留在後頭，", "cite": "三子者出，曾皙後", "mean": "曾皙很想知道孔子對另外三位的評價，故刻意留在後邊。自此對話者從五人變成二人，高明的描寫技巧，使本章讀來更像一篇有趣的極短篇小說。", "meanShort": "<b>曾皙殿後探問評價</b>：曾皙刻意留下詢問評價，對話轉折極具小說筆法。"}, {"text": "曾皙曰：「{n:38|夫}三子者之言何如？」", "tr": "問：「他們三位的話怎麼樣？」"}, {"text":"子曰：「亦各言其志{g:也已|句末助詞，罷了}矣。」","tr":"孔子：「也就是各自談談志向罷了。」","cite":"各言其志也已矣","mean":"此與前文「亦各言其志也」相呼應。「言志」二字是全文章法的主軸，故再度強調。","meanShort":"<b>強調主軸</b>：呼應前文，再次強調「言志」為全文章法主軸。","askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>「亦各言其志也已矣」</div>"}, {"text": "曰：「夫子何哂由也？」", "tr": "曾皙：「老師為什麼笑由呢？」", "cite": "夫子何哂由也", "mean": "曾皙觀察細心。"}, {"text":"曰：「{z:為|ㄨㄟˊ}國以禮，其言不{n:39|讓}，{g:是|此，指「為國以禮，其言不讓」}故哂之。」","tr":"孔子：「治國應當講禮，子路的話毫不謙讓，所以我笑他。」","mean":"孔子藉與曾皙的問答點明評志標準在『禮讓』：哂子路非否定其才，而在其『不讓』；冉有、公西華雖同為治國之志，因言辭謙退故不哂。全章歸結於『為國以禮』。","cite":"為國以禮，其言不讓","meanShort":"<b>點出評志標準</b>：點明標準在於「禮讓」，全章總結於「為國以禮」。","askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>「為國以禮，其言不讓，是故哂之」；讓＝謙讓（孔子明說）；朱熹：許其能，哂其不遜（注家解讀）</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>子路是否適合被任用</div><div class=\"tk-sep\"></div>朱熹注：「夫子蓋許其能，特哂其不遜。」","ask":["<div class=\"gd gd-one\" data-gq=\"s14\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑭</span>孔子笑子路，笑的是什麼？<div class=\"gd-qa\">「為國以禮，其言不讓」：笑他說話不謙讓，不是否定他的能力。</div></div><div class=\"gd-board vis\" onclick=\"gdTap(this)\"><span class=\"gd-bh\">孔子為什麼哂子路？</span><div class=\"gd-bt\"><div>為國以禮，<b>其言不讓</b>，是故哂之</div><div class=\"gd-bar\">↓</div><div>笑的不是<b>能力</b>，是<b>態度</b></div><div>對照：公西華「非曰能之，願學焉」＝<b>讓</b></div></div></div></div>"]}, {"text": "「{n:40|唯求則非邦也與}？」", "tr": "曾皙：「求所說的，不是治國的事嗎？（不然老師怎麼都沒有表示？）」"}, {"text":"「{n:41|安}見方六、七十，如五、六十，而非邦也者？」","tr":"孔子：「怎麼見得六、七十里或五、六十里見方的地方，不算一個國家呢？（因為冉求很謙虛，所以我沒表示什麼，但他所說的，當然是屬於治理國家的事。）」","rhet":[["激問","<span class=\"tp-rq\">安見方六、七十，如五、六十，而非邦也者</span>──答案在問題反面：當然是國家，肯定冉有所談也是治國之事。"]],"rhetShort":["肯定冉有所談也是治國之事"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>冉有談的仍是治國（「安見方六、七十，如五、六十，而非邦也者」）</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>未笑冉有是否也和他謙退有關（問話者的注疏異說只給老師，學生不必背）</div><div class=\"tk-sep\"></div>朱熹注：「曾點以冉求亦欲為國而不見哂，故微問之。而夫子之答無貶辭，蓋亦許之。」"}, {"text": "「唯赤則非邦也與？」", "tr": "曾皙：「赤所說的，不是治國的事嗎？（不然老師怎麼也沒有表示？）」"}, {"text":"「宗廟會同，{n:42|非諸侯而何}？{n:43|赤也為之小，孰能為之大}？」","tr":"孔子：「宗廟會同，不是諸侯的事又是什麼？公西華只能做小相，又有誰能做大相呢？」","rcite":["非諸侯而何"],"rhet":[["激問","<span class=\"tp-rq\">非諸侯而何</span>、<span class=\"tp-rq\">孰能為之大</span>──連用激問，肯定公西華的才能與謙遜。"]],"cite":"宗廟會同，非諸侯而何","mean":"「宗廟會同」與「諸侯（之事）」皆同為政治激問。","cite2":"赤也為之小，孰能為之大","mean2":"孔子肯定公西華的才能與謙遜。","rhetShort":["肯定公西華的才能與謙遜。"],"meanShort":"<b>政治激問</b>：以激問法指出「宗廟會同」與「諸侯之事」皆屬政治事務。","mean2Short":"<b>肯定公西華</b>：孔子肯定公西華的才華與謙遜。","ask":["<div class=\"gd gd-one\" data-gq=\"s15\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑮</span>孔子否定冉有、公西華了嗎？<div class=\"gd-qa\">沒有：小國也是國家；宗廟會同也是諸侯大事，「小相」只是謙稱。</div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>宗廟會同是諸侯大事；「赤也為之小，孰能為之大」；小相是謙稱</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>公西華是否有更大的政治能力（問話者異說同上，只給老師）</div><div class=\"tk-sep\"></div>朱熹注：「孰能為之大，言無能出其右者，亦許之之辭。」<br>「唯求／唯赤則非邦也與」誰問的：朱熹《集注》以為曾皙問、孔子答；皇侃、邢昺疏以為孔子自問自答。"}], "qa": [["本文描寫孔子課堂實況，在寫作技巧上有何特殊點？", "《論語》大多為單一人物之口述語錄，本文特殊處在於全文以對話的形式呈現：先以「侍坐」點出師生共同討論的場景；行文至一半才出現「鼓瑟希」，則使讀者赫然發現原來對話從一開始便是在音樂聲中進行的；最後則以「三子者出，曾皙後」交代對話者從五人變成二人。其類似小說的描寫技巧，使本文的情節充滿張力。"], ["本文呈現孔子哪些教育方法？", "本文表現出孔子有教無類、循循善誘、因材施教的教育方式。"], ["下列選項哪些是本文含括的題材內容？（多選）<br>□1.孔子要弟子談個人的志向<br>□2.子路表達帶軍布陣的志向<br>□3.冉有表達經濟富民的志向<br>□4.公西華要擔任贊禮司儀官<br>□5.曾皙表達隨遇而安的理想<br>□6.孔子要求學生要適性發展", "1、3、4"], ["下列選項哪些是本文所使用的寫作技巧？（多選）<br>□1.以對話方式行文敘事<br>□2.以「侍坐」點出場景<br>□3.採先分述再總評的布局", "1、2、3"]], "notes": [["夫", "ㄈㄨˊ，彼、那。<span class='tm-sup'>也可看作句首發語詞，不譯。</span>"], ["讓", "謙讓。"], ["唯求則非邦也與", "難道冉求所說的就不是治國的事嗎？唯，語首助詞。與（ㄩˊ），通『歟』。"], ["安", "何、怎麼。"], ["非諸侯而何", "如果不是和諸侯相關的國家大事又是什麼事呢？<span class='tm-sup'>而，卻。</span>"], ["赤也為之小，孰能為之大", "公西華謙稱只能做小相，又有誰能做大相呢？"]], "boxes": [{"label":"全課統整","ask":["<div class=\"gd gd-one\" data-gq=\"s16\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑯</span>如果有人願意重用你——四個人各從什麼地方想起？<div class=\"gd-qa\">子路：我有能力解決什麼問題？<br>冉有：我能負責到什麼程度？<br>公西華：我想在哪個領域貢獻自己？<br>曾皙：我理想中的生活是什麼樣子？</div></div><div class=\"gd-board vis\" onclick=\"gdTap(this)\"><span class=\"gd-bh\">《侍坐》人物線</span><div class=\"gd-bt\"><div>子路：<b>率爾而對</b> → 有勇、知方 → 有能力，但「不讓」</div><div class=\"gd-bar\">↓</div><div>冉有：<b>求也為之</b> → 足民；禮樂「以俟君子」</div><div class=\"gd-bar\">↓</div><div>公西華：<b>非曰能之，願學焉</b> → 宗廟會同的禮儀，自稱「小相」</div><div class=\"gd-bar\">↓</div><div>曾皙：<b>舍瑟而作</b> → 「異乎三子者之撰」→ 描繪嚮往的生活</div><div class=\"gd-bar\">↓</div><div>孔子：<b>喟然嘆曰：「吾與點也！」</b></div><div class=\"gd-bar\">↓</div><div>曾皙追問：「夫子何哂由也？」</div><div class=\"gd-bar\">↓</div><div>孔子說明：<b>為國以禮，其言不讓，是故哂之</b>；冉有、公西華談的也是國家大事</div></div></div></div>"],"askT":"<div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>人物線 孔子哂子路因「其言不讓」；冉有、公西華所談也是國家大事；贊同曾皙</div><div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>「內聖外王」語出《莊子．天下》，後世用來概括儒家理想；不是本篇用語</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>本課哪些內容可以對照這兩個面向</div><div class=\"tk-core\"><span class=\"tk-k\">考試核心</span>「知其不可而為之」（〈憲問〉，石門守門人評孔子）</div><div class=\"tk-open\"><span class=\"tk-k\">可討論</span>理想難以實現，是否值得堅持</div><div class=\"tk-sep\"></div><b>教師引導主軸</b>：孔子問志 → 三子言治 → 曾皙言境 → 孔子與點 → 孔子評三子。<br>「吾與點也」不必解成「前三人都錯了」，而是孔子認同曾皙所呈現的理想境界；第六段孔子仍替冉有、公西華說話。<br>周遊列國的經過見「孔子的一生」。<br><br><b>另一種看法</b>（與課本說法不同，可供討論）：對話停在肯定冉有、公西華，沒再多談曾皙，也許是提醒曾皙不要過於超脫，忘了儒家改善世界的責任。可對照「延伸·孔子之為人（三）」〈微子〉長沮、桀溺章，孔子不肯避世。<br><br><b>可用結語</b>：曾皙在亂世中畫出的這幅畫，就像在沙漠裡種花——看似不切實際，卻提醒大家：所有的努力與競爭，最終目的不是無止境的打仗或爭奪，而是讓每個人能平平安安、快樂地吹風唱歌。"}]}], "extras": {"authorPages": [{"label": "作者·補充｜春秋的士", "head": "春秋的士（作者補充）", "body": "<b class='dz-h'>一、封建制度的金字塔</b><br><img class='shi-pyr-img' src='img/侍坐/shi-fengjian.png' alt='周代封建宗法金字塔：天子、諸侯、大夫、士為貴族，其下為平民（農、工、商）與奴隸；嫡長子世襲爵位為大宗，庶子降級向下分封為小宗'>周代把天下一層一層分封下去，每一層都有自己的身分和禮制：<div class='sp-anc'>天子建國，諸侯立家，卿置側室，大夫有貳宗，士有隸子弟，庶人、工、商各有分親，皆有等衰。（《左傳．桓公二年》）</div>天子分封諸侯建國，諸侯再分封卿大夫……一層一層往下，<b>每一層都有等級差別</b>（等衰）。<br><br><b class='dz-h'>二、春秋：金字塔開始鬆動</b><br><div class='rj-evo'><span class='rj-step'><i>上層</i><b>周天子</b><em>地位低落</em></span><span class='rj-arr'>→</span><span class='rj-step'><i>中層</i><b>諸侯、大夫</b><em>篡弒、專權</em></span><span class='rj-arr'>→</span><span class='rj-step'><i>結果</i><b>禮崩樂壞</b><em>階級流動</em></span></div>孔子生在春秋末期：周天子地位低落，原本維持秩序的<b>宗法禮制名存實亡</b>，諸侯篡弒、權臣專權成為常態。魯國的<b>三桓</b>（季孫氏、叔孫氏、孟孫氏）把持朝政，季孫氏甚至在家裡跳只有天子才能用的「八佾」舞，孔子氣得說：<div class='sp-anc'>孔子謂季氏：「八佾舞於庭，是可忍也，孰不可忍也？」（〈八佾〉）</div>上下秩序亂了，階級也開始快速流動──這就是孔子說的「禮崩樂壞」的時代。<br><br><b class='dz-h'>三、孔子：從「士」出發</b><br>孔子的祖先是<b>宋國貴族</b>，避難逃到魯國後雖然當了大夫，卻沒有世襲的封地，地位等同於<b>士</b>。父親早死，孔子雖然出身貴族階級，卻從小過著貧困的生活，從<b>最基層的士職</b>做起：管倉庫的<b>委吏</b>、養牛羊的<b>乘田</b>。<div class='sp-anc'>吾少也賤，故多能鄙事。（〈子罕〉）</div><br><b class='dz-h'>四、私學：知識走出貴族圈</b><br>原本是「<b>學在官府</b>」：學問掌握在官府、貴族手裡。孔子三十歲左右開始在家講學，<b>有教無類</b>，只要備「束脩」之禮就收。私學的創設，打破「學在官府」的傳統，讓學術文化從貴族<b>往下流到民間</b>。<br><br><b class='dz-h'>五、《論語》裡的「士」</b><br>從此「士」不只是一種貴族身分，而是<b>有學問、有志向、能出來做事的人</b>。<div class='sp-anc'>子曰：「士志於道，而恥惡衣惡食者，未足與議也。」（〈里仁〉）</div>立志追求道，卻又以穿不好、吃不好為恥的人，不值得跟他談。<div class='sp-anc'>曾子曰：「士不可以不弘毅，任重而道遠。」（〈泰伯〉）</div>士一定要心胸寬廣、意志堅強，因為責任重大、路途遙遠。<div class='sp-anc'>子貢問曰：「何如斯可謂之士矣？」子曰：「行己有恥，使於四方，不辱君命，可謂士矣。」（〈子路〉）</div>做事有羞恥心，出使外國能完成國君交付的任務，就稱得上是士。"}, {"label": "作者·補充｜儒家", "head": "儒家（作者補充）", "body": "<b class='dz-h'>一、儒家是什麼</b><br>以孔子為宗師，代表人物是<b>孔子、孟子、荀子</b>。中心思想是<b class='rj-k'>仁</b>，主張忠恕、行仁政、崇尚禮樂，愛有差等。《漢書．藝文志》說儒家出於<b>司徒之官</b>（掌理教化）。戰國時，儒、墨兩家並稱「<b>顯學</b>」（當時最有名的學派）。<br><br><b class='dz-h'>二、儒家的教育：六藝</b><br>孔子教學生「<b>六藝</b>」：<b>禮、樂、射、御、書、數</b>六種科目。射是射箭、御是駕車──不只讀書，也要能拉弓、駕戰車（冉有就能帶兵打仗，見「弟子小檔案」）。<div class='sp-anc'>子曰：「志於道，據於德，依於仁，游於藝。」（〈述而〉）</div>立志在道，根據在德，依靠著仁，在六藝裡涵養自己。<br><br><b class='dz-h'>三、君子與聖人</b><br>儒家的目標可以說是「<b>內聖外王</b>」：<br>· <b>內聖</b>：先把自己修養好──成為<b class='rj-k'>君子</b>（有道德修養）、成為<b class='rj-k'>士</b>（有官位的知識份子），最高是<b class='rj-k'>聖人</b>（道德的最高標準）。<br>· <b>外王</b>：自己成材了，出來做事，推己及人，讓更多人過更好的生活。<div class='sp-anc'>子路問君子。子曰：「修己以敬。」曰：「如斯而已乎？」曰：「修己以安人。」曰：「如斯而已乎？」曰：「修己以安百姓。修己以安百姓，堯舜其猶病諸！」（〈憲問〉）</div><div class='rj-evo'><span class='rj-step'><i>第一層</i><b>修己以敬</b><em>修養自己</em></span><span class='rj-arr'>→</span><span class='rj-step'><i>第二層</i><b>修己以安人</b><em>讓身邊的人安樂</em></span><span class='rj-arr'>→</span><span class='rj-step'><i>第三層</i><b>修己以安百姓</b><em>連堯舜都難做到</em></span></div>問「君子」的就是〈侍坐〉裡的<b>子路</b>，孔子一層一層往上推給他看。<div class='sp-anc'>子貢曰：「如有博施於民而能濟眾，何如？可謂仁乎？」子曰：「何事於仁，必也聖乎！堯舜其猶病諸！」（〈雍也〉）</div>能廣泛施恩給百姓、救助大眾的人，那已經不只是仁，一定是<b>聖</b>了，連堯、舜都怕做不到。<br><br><b class='dz-h'>四、和道家、墨家、法家比一比</b><br><table class='ly-table rj-tb rj-tb4'><tr><th>學派</th><th>代表人物</th><th>主張</th></tr><tr><td>儒家</td><td>孔子、孟子（性善）、荀子（性惡）</td><td>中心思想是<b class='rj-k'>仁</b>，主忠恕、行仁政、崇尚禮樂，<b class='rj-k'>愛有差等</b></td></tr><tr><td>道家</td><td>老子（無為）、莊子（齊物）</td><td>崇尚<b class='rj-k'>自然</b>，<b class='rj-k'>清靜無為</b>；莊子自由達觀</td></tr><tr><td>墨家</td><td>墨子（墨翟）</td><td><b class='rj-k'>兼愛、非攻</b>、尚賢、尚同、節用、節葬、非樂、非命；<b class='rj-k'>愛無差等</b>，反對攻伐他國的不義之戰</td></tr><tr><td>法家</td><td>商鞅（重法）、申不害（重術）、慎到（重勢）、韓非（集大成）</td><td>嚴賞罰、<b class='rj-k'>貴法治</b>，以嚴刑重罰維持安定，嚴而少恩</td></tr></table>儒家講「愛有差等」（先愛親人，再推及他人），墨家講「愛無差等」（對所有人同樣地愛）。<br><br><b class='dz-h'>五、孔子→孟子→荀子</b><br><div class='rj-evo'><span class='rj-step'><i>春秋</i><b>孔子</b><em>仁</em></span><span class='rj-arr'>→</span><span class='rj-step'><i>戰國</i><b>孟子</b><em>義</em></span><span class='rj-arr'>→</span><span class='rj-step'><i>戰國</i><b>荀子</b><em>禮</em></span></div><table class='ly-table rj-tb'><tr><th></th><th>孔子</th><th>孟子</th><th>荀子</th></tr><tr><td>名字</td><td>名丘，字仲尼</td><td>名軻，字子輿</td><td>名況</td></tr><tr><td>籍貫</td><td>春秋魯人</td><td>戰國鄒人</td><td>戰國趙人</td></tr><tr><td>中心思想</td><td><b class='rj-k'>仁</b></td><td><b class='rj-k'>義</b></td><td><b class='rj-k'>禮</b></td></tr><tr><td>人性</td><td>—</td><td><b>性善</b>：人性本來就是善良的</td><td><b>性惡</b>：人性好逸惡勞，要靠後天教育「化性起偽」才能向善</td></tr><tr><td>主張</td><td>主忠恕；行仁政、正名分；有教無類、因材施教；依魯史修《春秋》</td><td>重義輕利、先義後利；<b>民貴君輕</b>；<b>尊王賤霸</b>（推崇以德服人的王道，反對以力服人的霸道）</td><td>重視禮樂與學習</td></tr><tr><td>效法</td><td>—</td><td>法先王（堯、舜、禹、湯）</td><td>法後王（文、武、周公）</td></tr></table><br><br><b class='dz-h'>六、漢代：從黃老到獨尊儒術</b><br><div class='rj-flow'><span class='rj-f'>漢初<br><b>黃老治術</b></span><span class='rj-arr'>→</span><span class='rj-f'>漢武帝<br><b>獨尊儒術</b></span><span class='rj-arr'>→</span><span class='rj-f'>漢宣帝<br><b>儒表法裡</b></span></div><b class='rj-n'>① 漢初：黃老治術</b>　曹參當齊國丞相，請來精通黃老之學的蓋公，用「清靜」治國，齊國安定。<div class='sp-anc'>聞膠西有蓋公，善治黃老言，使人厚幣請之。既見蓋公，蓋公為言治道貴清靜而民自定，推此類具言之。參於是避正堂，舍蓋公焉。其治要用黃老術，故相齊九年，齊國安集，大稱賢相。（《史記．曹相國世家》）</div><b class='rj-n'>② 漢武帝：罷黜百家，獨尊儒術</b>　董仲舒建議：不在六藝、不屬孔子之學的，一律斷絕，不讓它們和儒學並進，思想才能統一。<div class='sp-anc'>春秋大一統者，天地之常經，古今之通誼也。今師異道，人異論，百家殊方，指意不同，是以上亡以持一統；法制數變，下不知所守。臣愚以為諸不在六蓺之科孔子之術者，皆絕其道，勿使並進。邪辟之說滅息，然後統紀可一而法度可明，民知所從矣。（《漢書．董仲舒傳》）</div><b class='rj-n'>③ 漢宣帝：儒表法裡</b>　太子（後來的漢元帝）勸宣帝多用儒生，宣帝說漢朝制度本來就是<b>霸道（法家）、王道（儒家）</b>混著用，不能只靠德教。表面尊儒、實際用法，後人稱為「儒表法裡」。<div class='sp-anc'>漢家自有制度，本以霸王道雜之，奈何純任德教，用周政乎！且俗儒不達時宜，好是古非今，使人眩於名實，不知所守，何足委任！（《漢書．元帝紀》）</div><b class='dz-h'>七、之後</b><br>南宋朱熹編定「四書」，作《四書章句集注》，四書成為儒家入門書；元代以後四書成為科舉必考，直到清末廢科舉為止。"}, {"label": "作者·課本", "head": "孔子（課本作者介紹）", "body": "<div class=\"au-fig\"><img class=\"au-img\" src=\"img/侍坐/kongzi-teacher.jpg\" alt=\"孔子與弟子（示意圖）\"><div class=\"au-cap\">◀ 孔子與弟子（示意圖）</div></div>孔子名丘，字仲尼，春秋魯國陬邑（今山東省曲阜市）人。生於魯襄公二十二年（西元前五五一年），卒於魯哀公十六年（西元前四七九年），年七十三。孔子三歲喪父，由母親扶養成人。為了謀生，他做過許多卑微的工作。三十歲開始講學，五十二歲擔任魯國大司寇（主掌司法、刑獄及社會治安），在外交和內政上均有建樹。後因魯君荒於政事，孔子失望之餘，帶領弟子周遊列國，尋求仕進，可惜未能獲得任用。六十八歲回到魯國，投身教育，並整理《詩》、《書》、《禮》、《樂》、《易》、《春秋》。孔子思想以「仁」為中心，「忠、恕」為行仁的方法，重視禮樂教化。他首開平民教育之風，有教無類，因材施教，後世尊稱為「至聖先師」、「萬世師表」。", "supList": [["名丘", "孔子出生時，生而首上「圩頂」（圩，中間低而四周高起），所以取名孔丘。"], ["至聖先師", "明世宗嘉靖九年（一五三○）追諡。"], ["因材施教", "針對學生不同的個性、資質給予不同的教導。本文孔子對子路『哂之』、對曾皙『與之』，即因材施教的展現。"], ["忠、恕", "《論語．里仁》中，曾子說：「夫子之道，忠恕而已矣。」孔子的中心思想「仁」便由「忠恕」貫徹實踐。《論語集註》中，朱熹曾言：「盡己之謂忠，推己之謂恕。」簡而言之，「忠」是竭盡自己的心力，「恕」是推己及人，「親親而仁民，仁民而愛物」、「老吾老以及人之老，幼吾幼以及人之幼」。「忠恕」促使「仁」有了具體落實的內容，有了明確執行的方法，同時奠定儒家愛人愛己，愛有等差的思想觀。"], ["有教無類", "不分貴賤、貧富、地域，只要備『束脩』之禮即可受教。"]]}, {"label": "作者·補充｜孔子的一生", "head": "孔子的一生（作者補充）", "body": "<div class=\"kzl\"></div>"}, {"label": "作者·補充｜政治與教育主張", "head": "孔子的政治與教育主張（作者補充）", "body": "<b>政治</b><div class='sp-anc'>子貢問政。子曰：「足食。足兵。民信之矣。」子貢曰：「必不得已而去，於斯三者何先？」曰：「去兵。」……曰：「去食。自古皆有死，民無信不立。」（〈顏淵〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>子貢問怎麼施政。孔子說：「使糧食充足，軍備充實，人民信任政府。」子貢說：「如果不得已必須要刪去，在這三項中該先去除哪一項呢？」孔子說：「去掉軍備。」……孔子說：「去掉糧食。自古以來，人都免不了死亡，但沒有人民的信任，國家就要滅亡。」</div>糧食、軍備、人民的信任，最不能丟的是<b>信</b>。<br><br><div class='sp-anc'>有若對曰：「百姓足，君孰與不足？百姓不足，君孰與足？」（〈顏淵〉）</div>這是孔子弟子有若對魯哀公說的：人民富足，國君才會富足。<br><br>→ 對照〈侍坐〉：子路講兵（有勇）、冉有講富（足民）、公西華講禮，孔子的評語是「為國以禮」。<br><br><b>教育：因材施教</b><div class='sp-anc'>子游問孝。子曰：「今之孝者，是謂能養。至於犬馬，皆能有養；不敬，何以別乎？」（〈為政〉）<br>子夏問孝。子曰：「色難。……」（〈為政〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>子游問孝道。孔子說：「現在所謂的孝順，只是能以飲食供奉父母。至於狗和馬，人也能以食物來豢養；若只是提供雙親食物而不存敬意，則與養狗和馬有何分別？」<br>色難：以和顏悅色最為難得。</div>同樣問孝，對子游說要<b>敬</b>（只養不敬，和養狗養馬沒兩樣）；對子夏說難在<b>和顏悅色</b>——同一個問題，依學生的不同給不同的答案（另見「弟子小檔案」子路條）。<br>"}, {"label": "作者·補充｜弟子小檔案", "head": "弟子小檔案（補充・免抄）", "body": "<div class='sp-anc'>子曰：「從我於陳、蔡者，皆不及門也。」德行：顏淵，閔子騫，冉伯牛，仲弓。言語：宰我，子貢。政事：冉有，季路。文學：子游，子夏。（〈先進〉）</div>孔子晚年想起當年跟著他在陳、蔡之間受困挨餓的學生，接著列出「<b>孔門四科十哲</b>」。本課的冉有、子路（季路）都在「政事」科；〈侍坐〉也在〈先進〉篇。<br><button class=\"ah-link\" onclick=\"wkGoHandout(event,&quot;四科十哲&quot;)\">→ 看補充講義：四科十哲</button><br><br><b class='dz-g'>（一）十哲裡的兩位：顏淵、子貢</b><br><b class='dz-h'>顏淵（顏回）</b><img class='dz-img' src='img/侍坐/dz-yanhui.jpg' alt='顏淵'><br>· 德行科第一位，孔子最喜愛的學生。<br>· 吃住都簡陋，別人受不了，他照樣快樂：<div class='sp-anc'>子曰：「賢哉回也！一簞食，一瓢飲，在陋巷，人不堪其憂，回也不改其樂。賢哉回也！」（〈雍也〉）</div>· 哀公問哪個學生好學，孔子說：「有顏回者好學，不遷怒，不貳過。不幸短命死矣！」（〈雍也〉）——不把怒氣發到別人身上，同樣的錯不犯第二次。<br>· 匡城被圍，顏淵落在後面才到。孔子說：「吾以女為死矣。」顏淵說：「子在，回何敢死？」（〈先進〉）——老師還在，我怎麼敢死？<br>· 「回年二十九，髮盡白，蚤死。」（《史記・仲尼弟子列傳》）顏淵死，孔子說：「噫！天喪予！天喪予！」（〈先進〉）——這是老天要亡我啊！<br><br><b class='dz-h'>子貢（端木賜）</b><img class='dz-img' src='img/侍坐/dz-zigong.jpg' alt='子貢'><br>· 言語科。「利口巧辭，孔子常黜其辯。」（《史記・仲尼弟子列傳》）——口才好、很會辯，孔子常壓一壓他。<br>· 很會做生意：「賜不受命，而貨殖焉，億則屢中。」（〈先進〉）——不安於命去經商，猜行情常常猜中；後來「家累千金」（《史記・仲尼弟子列傳》）。<br>· 陳、蔡絕糧時，派子貢去楚國求救，楚王派兵來接，大家才脫險：<div class='sp-anc'>於是使子貢至楚。楚昭王興師迎孔子，然後得免。（《史記・孔子世家》）</div>· 孔子死後，弟子守喪三年，只有子貢又多住了三年。<br><br><b class='dz-g'>（二）〈侍坐〉的四位弟子</b><br><b class='dz-h'>子路（仲由）</b><img class='dz-img' src='img/侍坐/dz-zilu.jpg' alt='子路'><br>· 年輕時像不良少年：<div class='sp-anc'>子路性鄙，好勇力，志伉直，冠雄雞，佩豭豚，陵暴孔子。（《史記・仲尼弟子列傳》）</div>戴公雞毛的帽子、佩公豬皮，還欺負孔子；孔子「設禮稍誘子路」，用禮慢慢引導，子路後來「儒服委質」，穿上儒服拜師入門。<br>· 「求也退，故進之；由也兼人，故退之。」（〈先進〉）——子路勇氣抵兩個人，孔子要拉住他；冉有退縮，孔子要推他一把。這就是因材施教。<br>· 「子見南子，子路不說。」（〈雍也〉）——直率到敢給老師臉色看，孔子只好發誓：「天厭之！天厭之！」<br>· 年輕時「為親負米百里之外」，孔子稱讚他「生事盡力，死事盡思」。（《孔子家語・致思》）<br>· 死於衛國內亂：帽帶被戈砍斷，說「君子死，冠不免」，「結纓而死」。（《左傳・哀公十五年》）孔子在中庭哭子路，聽說他被剁成肉醬，「遂命覆醢」——把家裡的肉醬倒掉。（《禮記・檀弓上》）<br><br><b class='dz-h'>冉有（冉求）</b><img class='dz-img' src='img/侍坐/dz-ranyou.jpg' alt='冉有'><br>· 「求也藝，於從政乎何有？」（〈雍也〉）——多才多藝，從政沒問題。<br>· 也能打仗：「冉有用矛於齊師，故能入其軍。」（《左傳・哀公十一年》）季康子問他帶兵的本事是學的還是天生的，冉有說：「學之於孔子。」（《史記・孔子世家》）<br><br><b class='dz-h'>公西華（公西赤）</b><img class='dz-img' src='img/侍坐/dz-gongxihua.jpg' alt='公西華'><br>· 孔子的喪禮由他負責：「孔子之喪，公西赤為志焉。」（《禮記・檀弓上》）——果然是禮儀專家。<br>· 「公西華之養親也，若與朋友處。」（《淮南子・齊俗訓》）——奉養父母像和朋友相處一樣自在。<br><br><b class='dz-h'>曾皙（曾點）</b><img class='dz-img' src='img/侍坐/dz-zengxi.jpg' alt='曾皙'><br>· 曾參的父親。程子說曾點是「狂者」，「未必能為聖人之事，而能知夫子之志」。（朱熹《論語集注》引）<br><br>"}], "intro": [{"label": "題解·課本", "head": "題解（課本）", "body": "本文選自《論語・先進》，為〈先進〉篇最後一章，原文無標題，標題乃編者所訂。「侍坐」，指陪侍於孔子座側。全文記錄孔子與學生的日常對話：從孔子引導學生暢談志向，看出學生的政治抱負及人格特質。在敞開心胸抒發情懷的對談中，孔子隨機啟發、循循善誘的教學方式，能感受到輕鬆卻充實的課堂氣氛；而孔子對曾皙的讚許，更透露出儒家淑世的精神與期許世界大同的襟懷。《論語》各章多為簡要語錄，然而本章卻超過四百字，結構完整，人物形象鮮明，在《論語》中極為特出。", "supList": [["循循善誘", "善於循序漸進地誘導別人。〈子罕〉：『夫子循循然善誘人，博我以文，約我以禮。』"], ["《論語・先進》", "《論語》是孔子弟子及再傳弟子記錄孔子言行的語錄體經典，共二十篇；南宋朱熹將它與《孟子》、〈大學〉、〈中庸〉合為「四書」。<br><b>易錯</b>：「四書」是南宋朱熹才合稱的，不是漢代。<span class='tm-sup'>【98指考】曾以「漢代獨尊儒術……論語……與孟子、大學、中庸合稱為四書」當錯誤敘述。</span><br><br><b>怎麼讀《論語》</b><div class='sp-anc'>程子曰：「學者須將《論語》中諸弟子問處便作自己問，聖人答處便作今日耳聞，自然有得。」<br>程子曰：「人只看得二書切己，終身盡多也。」</div><span>程子語見朱熹〈讀論語孟子法〉。</span>"], ["簡要語錄", "語錄體：直接記錄講學、論政等言論的文體，以記錄對話為主，短小精巧；《論語》是語錄體的典範。<br><b>一盤珍珠</b>：《論語》一章就是一則語錄，章與章之間沒有前後邏輯，像一盤珍珠直接放進盒子；篇名只是標籤，可當頁碼看。全書二十篇，約四百九十二章（各家分章略有不同）。"]]}, {"label": "題解·補充｜《論語》詳表", "head": "《論語》詳表（題解補充）", "body": "《漢書．藝文志》記載：「《論語》者，孔子應答弟子、時人，及弟子相與言而接聞於夫子之語也。當時弟子各有所記，夫子既卒，門人相與輯而論纂，故謂之《論語》。」<br><br><b>篇名與章數</b>：現在通行的《論語》是以東漢鄭玄〈注〉為準的《論語》，共計二十篇（起於〈學而〉，終於〈堯曰〉）。<table class=\"ly-table ly-grid\"><tbody><tr><td>1.〈學而〉</td><td>2.〈為政〉</td><td>3.〈八佾〉</td><td>4.〈里仁〉</td></tr><tr><td>5.〈公冶長〉</td><td>6.〈雍也〉</td><td>7.〈述而〉</td><td>8.〈泰伯〉</td></tr><tr><td>9.〈子罕〉</td><td>10.〈鄉黨〉</td><td>11.〈先進〉</td><td>12.〈顏淵〉</td></tr><tr><td>13.〈子路〉</td><td>14.〈憲問〉</td><td>15.〈衛靈公〉</td><td>16.〈季氏〉</td></tr><tr><td>17.〈陽貨〉</td><td>18.〈微子〉</td><td>19.〈子張〉</td><td>20.〈堯曰〉</td></tr></tbody></table><br><table class=\"ly-table\"><thead><tr><th>項目</th><th>《論語》</th></tr></thead><tbody><tr><td>撰者</td><td>孔子弟子與再傳弟子（作者並非孔子本人）</td></tr><tr><td>異稱</td><td>亦可稱《論》或《語》，漢以後《論語》之名方漸趨確定。</td></tr><tr><td>數量</td><td>今本共20篇，分為上、下兩部</td></tr><tr><td>上部</td><td>計有〈學而〉、〈為政〉、〈八佾〉、〈里仁〉、〈公冶長〉、〈雍也〉、〈述而〉、〈泰伯〉、〈子罕〉、〈鄉黨〉等十篇。</td></tr><tr><td>下部</td><td>計有〈先進〉、〈顏淵〉、〈子路〉、〈憲問〉、〈衛靈公〉、〈季氏〉、〈陽貨〉、〈微子〉、〈子張〉、〈堯曰〉等十篇。</td></tr><tr><td>篇名</td><td>大抵取首章起始的二、三字作為篇名，篇名與該篇內容並無關聯。</td></tr><tr><td>中心思想</td><td>以「仁」為核心，顯現孔子政治、倫理、教育、道德修養等思想</td></tr><tr><td>內容</td><td>(1)關於個人人格修養的教言。<br>(2)關於社會倫理的論述。<br>(3)關於政治哲學的闡述。<br>(4)關於人生哲學的闡述。<br>(5)對孔門弟子及時人因材施教的問答。<br>(6)對孔門弟子及古人、時人的批評。<br>(7)孔子自述之言。<br>(8)孔子的出處與日常行事。<br>(9)孔門弟子對孔子的頌美與時人對孔子的評論。<br>(10)孔門弟子的言論行事。</td></tr><tr><td>歷史地位</td><td>唐文宗時，列為十二經之一。南宋光宗時，列為十三經之一。南宋朱熹將《論語》、《孟子》、〈大學〉、〈中庸〉合稱四書，並為之作《四書章句集注》。</td></tr><tr><td>後世評論</td><td>北宋趙普嘗謂宋太宗曰：「臣有《論語》一部，以半部佐太祖定天下，以半部佐陛下致太平。」後人即以「半部《論語》治天下」評之。</td></tr></tbody></table><br><b>〈學而〉</b>：《論語》的第一篇，起於首句「學而時習之，不亦說乎？」（語譯：學習之後又時時加以溫習，不是很喜悅嗎？）而得名，此篇主要論述君子孝悌、仁人忠信等，朱子集注嘗說：「學者之先務也。」是成為君子的基本入門方法。<br><b>〈堯曰〉</b>：《論語》的最後一篇，起於首句「堯曰：『咨！爾舜！天之曆數在爾躬。允執其中。』」而得名，此篇記錄了堯舜湯武及孔子等人之言論，主要闡述聖人之道，以垂訓後世。<br><b>半部《論語》治天下</b>：北宋宰相趙普輔佐宋太祖統一全國，宋太祖逝世，宋太宗即位，曾有人認為趙普不學無術，僅懂《論語》一書，不適宜擔任宰相。趙普說明自己是以半部《論語》輔佐太祖平定天下，而今，則是以「半部《論語》治天下」。<br><b>後世士人必讀之書</b>：南宋朱熹將儒家的重要經典《論語》、《孟子》、〈大學〉、〈中庸〉集注成《四書章句集注》。元仁宗延祐二年時定為科舉考試的範疇，明清時亦奉為科舉之準則，對後世的學術、政治、思想、文化影響深遠。"}, {"label": "寫作背景", "head": "寫作背景", "body": "孔門講學本在用世：子路長於治軍，冉有長於理財，公西華長於外交禮節，三人所學各有專長；曾皙則放情於山水、從容自樂於日常。就本章內容而言，師生討論言志，當在生活比較安穩的時期。<br><br><b>文化經典《論語》概述</b><br>《論語》成書背景源自禮樂崩壞的春秋末年，孔子無意出仕，進而撰書講學。由孔子弟子及再傳弟子編纂而成，主要記載孔子言行及與學生、時人的互動。孔子的生命經歷及其與弟子、時人的互動對話便成了《論語》一書的創作元素，孔子後學們藉此傳承其思想及精神。"}], "supplement": [{"label":"統整·四弟子志向總整理","head":"四弟子志向總整理（點空格顯示答案）","body":"<table class=\"ly-table\"><thead><tr><th></th><th>子路</th><th>冉有</th><th>公西華</th><th>曾皙</th></tr></thead><tbody><tr><th>志向</th><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>千乘之國，使有勇、知方</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>小國，使足民；禮樂待君子</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>宗廟會同，願為小相</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>暮春出遊，浴沂、風雩、詠歸</span></span></td></tr><tr><th>專長</th><td>軍事</td><td>理財、政事</td><td>禮儀、外交</td><td>—（不談事功）</td></tr><tr><th>說話態度</th><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>率爾，不讓</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>謙退（越說越小）</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>更謙（非曰能之，願學焉）</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>從容（鼓瑟希，舍瑟而作）</span></span></td></tr><tr><th>孔子反應</th><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>哂之</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>當場不置可否，事後替他說話</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>當場不置可否，事後替他說話</span></span></td><td><span class='jy-blank' onclick=\"this.classList.toggle('show')\"><span class='jy-blank-ph'>&nbsp;&nbsp;&nbsp;&nbsp;</span><span class='jy-blank-ans'>喟然嘆：吾與點也</span></span></td></tr></tbody></table><br>孔子的三種態度：對子路<b>微笑</b>（不以為然，但不說破）；對冉有、公西華<b>不表可否</b>；對曾皙<b>表示贊同</b>。<br>"},{"label":"課後延伸·談志（六題）","head":"課後延伸｜談「志」","body":"<div class=\"gd-after\"><div class=\"gd gd-one\" data-gq=\"a1\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">①</span>小時候想做的事，和現在想的一樣嗎？「志」可以是什麼？<div class=\"gd-qa\">志可以是目標、想成為的人，也可以是想過的生活；會隨經驗改變。</div></div></div><div class=\"gd gd-one\" data-gq=\"a2\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">②</span>「不知道自己要什麼」和「什麼都不要」一樣嗎？<div class=\"gd-qa\">不一樣。可能只是還沒找到方向，仍在探索。</div></div></div><div class=\"gd gd-one\" data-gq=\"a3\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">③</span>每天都能過著讓自己覺得「真好」的生活，算一種志嗎？<div class=\"gd-qa\">算。想過的生活也可以是志，但需要一些現實條件支持。</div></div></div><div class=\"gd gd-one\" data-gq=\"a4\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">④</span>你喜歡打電動的哪個部分？生活中還有什麼也能帶給你同樣感受？<div class=\"gd-qa\">可能是挑戰、成就、合作、創造或陪伴；這些感受也能在其他活動中找到。</div></div></div><div class=\"gd gd-one\" data-gq=\"a5\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑤</span>興趣一定是一開始就有的嗎？<div class=\"gd-qa\">不一定。可能先接觸、嘗試，才發現有趣並願意持續投入。</div></div></div><div class=\"gd gd-one\" data-gq=\"a6\"><div class=\"gd-q\" onclick=\"gdTap(this)\"><span class=\"gd-tag\">⑥</span>如果孔子現在問你：「如或知爾，則何以哉？」你會怎麼回答？<div class=\"gd-qa\">可以寫：我想＿＿＿；我對＿＿＿有興趣但還不確定；我願意先試試＿＿＿。</div></div></div></div>"},{"label":"課後引導·①「志」是什麼","head":"課後引導①　「志」是什麼？","body":"<div class=\"ah\"><div class=\"ah-step on\"><div class=\"ah-ask\"><span class=\"ah-k\">想一想</span>小時候被問「長大想做什麼」，你回答過什麼？<small>想得起來的都可以。</small></div><div class=\"wc\" data-w=\"老師:2|警察:2|醫生:2|太空人:1|YouTuber:3|有錢人:2|跟爸爸一樣:2|開店:1|不知道:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>現在被問同一個問題，你的答案變了嗎？為什麼會變？</div><div class=\"wc\" data-w=\"變了:3|比較實際了:3|看到家人很辛苦:2|發現自己有興趣的事:2|知道要考證照:2|想先賺錢:2|還是不知道:2|沒變:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>所以，「志」是什麼？用你自己的話說說看。</div><div class=\"wc\" data-w=\"夢想:3|目標:3|想做的事:2|想成為的人:2|想過的生活:2|方向:2|理想:2|未來的工作:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step ah-end\"><div class=\"ah-ask\"><span class=\"ah-k\">小結</span>志，是你對「想往哪裡去、想怎麼生活」慢慢形成的想法，而且會隨著長大改變。</div></div><button class=\"ah-next\" onclick=\"ahNext(this)\">下一步 ▸</button></div>"},{"label":"課後引導·②沒有志呢","head":"課後引導②　如果沒有志呢？","body":"<div class=\"ah\"><div class=\"ah-step on\"><div class=\"ah-ask\"><span class=\"ah-k\">想一想</span>被問「你的志向是什麼」的時候，你心裡第一個反應是什麼？<small>說實話就好。</small></div><div class=\"wc\" data-w=\"好難:3|不知道:3|又來了:2|很煩:2|隨便說一個:2|有點慌:2|想很久:1|早就想好了:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>「不知道自己要什麼」和「什麼都不要」，一樣嗎？</div><div class=\"wc\" data-w=\"不一樣:3|還沒找到:2|還在試:2|只是還沒說出口:2|其實有想要:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>所以，現在還不知道自己的志向，代表沒有志嗎？</div><div class=\"wc\" data-w=\"不代表:3|只是還沒想清楚:3|還在找:2|需要時間:2|先過好現在:2|代表沒有:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step ah-end\"><div class=\"ah-ask\"><span class=\"ah-k\">小結</span>還不知道，不等於沒有志；有些方向，只是還沒有被自己發現。</div></div><button class=\"ah-next\" onclick=\"ahNext(this)\">下一步 ▸</button></div>"},{"label":"課後引導·③小確幸算志嗎","head":"課後引導③　小確幸，算不算志？","body":"<div class=\"ah\"><div class=\"ah-step on\"><div class=\"ah-ask\"><span class=\"ah-k\">想一想</span>你最近一次覺得「這樣過日子真好」，是什麼時候？<small>想一個畫面。</small></div><div class=\"wc\" data-w=\"放假睡到自然醒:3|跟朋友吃宵夜:3|考完試:2|領到打工薪水:2|全家一起吃飯:2|騎車兜風:2|天氣很好:1|打球流汗:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>如果以後每天都能這樣過，這算不算一種志？</div><div class=\"wc\" data-w=\"算:3|不算:2|太小了吧:1|很實在:2|這就是我要的:2|也是一種生活目標:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>要過這樣的日子，需要哪些條件？</div><div class=\"wc\" data-w=\"有工作:3|有錢:3|有時間:2|身體健康:2|有朋友:2|家人平安:2|社會安定:3|不打仗:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>回頭看曾皙：他想要的只是自己過得舒服，還是希望大家都能過這樣的生活？<small>沒有標準答案，說出你從課文看到的理由。</small></div><div class=\"wc\" data-w=\"希望大家都能:3|只是自己嚮往的生活:2|兩者都有:3|大人小孩一起:2|自己舒服就好:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step ah-end\"><div class=\"ah-ask\"><span class=\"ah-k\">小結</span>想過的生活也是一種志。曾皙描繪的，不是治理方法，而是一種安定、自在、和樂的生活情境。</div></div><button class=\"ah-next\" onclick=\"ahNext(this)\">下一步 ▸</button></div>"},{"label":"課後引導·④只想打電動","head":"課後引導④　「我只想打電動」","body":"<div class=\"ah\"><div class=\"ah-step on\"><div class=\"ah-ask\"><span class=\"ah-k\">想一想</span>有人說：「我的志，就是以後每天打電動。」——這算不算志？<small>先不急著說對或錯。</small></div><div class=\"wc\" data-w=\"算:3|不算:2|看情況:2|如果能賺錢就算:2|電競選手:2|實況主:2|太爽了吧:1|這是逃避吧:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>你自己打電動的時候，什麼時候最開心？<small>想一個最近的畫面。</small></div><div class=\"wc\" data-w=\"贏的時候:3|終於破關:3|跟朋友一起打:3|想到好戰術:2|抽到好角色:1|把城蓋好:2|操作很順:2|被隊友稱讚:2|什麼都不用想:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>所以你喜歡的，是「打電動」這件事，還是遊戲給你的某種感覺？<small>把剛剛的開心，換成一個詞。</small></div><div class=\"wc\" data-w=\"成就感:3|挑戰:2|合作:2|被看見:2|創造:2|掌控感:2|放鬆:2|陪伴:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>除了遊戲，生活裡還有哪裡也能給你這種感覺？</div><div class=\"wc\" data-w=\"把壞掉的東西修好:3|自己畫的圖蓋成真的:2|跟同學一起完成作品:2|球隊比賽:2|考到一張證照:2|幫家人解決問題:2|做出好吃的料理:1|學會一首歌:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">選答</span>如果每天打電動，必須靠它養活自己，你還會一樣喜歡嗎？<small>興趣變成工作，可能會有什麼改變？（時間夠再討論）</small></div><div class=\"wc\" data-w=\"會:2|不一定:3|壓力變大:2|變成工作就不好玩:2|要練很久:2|看收入:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step ah-end\"><div class=\"ah-ask\"><span class=\"ah-k\">小結</span>有時候，我們喜歡的不只是某件事本身，而是它帶給自己的感受。找到這份感受，也許就能找到更多可能的方向。</div></div><button class=\"ah-next\" onclick=\"ahNext(this)\">下一步 ▸</button></div>"},{"label":"課後引導·⑤興趣從哪裡來","head":"課後引導⑤　興趣從哪裡來？","body":"<div class=\"ah\"><div class=\"ah-step on\"><div class=\"ah-ask\"><span class=\"ah-k\">想一想</span>你現在喜歡的一件事，一開始是怎麼接觸到的？</div><div class=\"wc\" data-w=\"朋友帶的:3|家人影響:2|偶然看到:2|被逼的:2|上課學到:2|看影片:2|打工遇到:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>一開始就喜歡嗎？還是做了一陣子才喜歡？</div><div class=\"wc\" data-w=\"一開始就喜歡:2|後來才喜歡:3|做得好就喜歡了:3|被稱讚以後:2|本來很討厭:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>有沒有什麼事，你本來以為會喜歡，試了才發現不喜歡？</div><div class=\"wc\" data-w=\"某個社團:2|某種運動:2|學樂器:2|某份打工:2|某個科目:2|某款遊戲:1\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>一件原本不熟悉的事，可能怎麼慢慢變成自己的興趣？<small>這是一種可能的路徑，不是每個人都一樣。</small></div><div class=\"ah-flow\"><span style=\"animation-delay:0.0s\">接觸</span><i style=\"animation-delay:0.3s\">→</i><span style=\"animation-delay:0.6s\">嘗試</span><i style=\"animation-delay:0.9s\">→</i><span style=\"animation-delay:1.2s\">發現有趣或獲得成就感</span><i style=\"animation-delay:1.5s\">→</i><span style=\"animation-delay:1.8s\">願意繼續投入</span><i style=\"animation-delay:2.1s\">→</i><span style=\"animation-delay:2.4s\">慢慢形成方向</span></div></div><div class=\"ah-step ah-end\"><div class=\"ah-ask\"><span class=\"ah-k\">小結</span>興趣不一定一開始就存在；有時候是先接觸、先嘗試，才慢慢發現自己願意投入什麼。</div></div><button class=\"ah-next\" onclick=\"ahNext(this)\">下一步 ▸</button></div>"},{"label":"課後引導·⑥我目前的方向","head":"課後引導⑥　我目前的方向","body":"<div class=\"ah\"><div class=\"ah-step on\"><div class=\"ah-ask\"><span class=\"ah-k\">想一想</span>回想〈侍坐〉四個人的回答，哪一句最讓你有感覺？</div><div class=\"wc\" data-w=\"由也為之:2|可使足民:2|非曰能之，願學焉:2|浴乎沂:2|詠而歸:3|吾與點也:2|如或知爾:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>四個人的回答方式各不相同。你目前比較認同哪一種？為什麼？<small>子路：行動型　冉有：務實型　公西華：學習型　曾皙：理想型——只是幫助理解四種不同的志向表達方式，不是人格類型；可以認同不只一種，也可以都不認同。</small></div><div class=\"wc\" data-w=\"子路:3|冉有:3|公西華:3|曾皙:3|都有一點:2|都不認同:2|還不知道:2\"></div><button class=\"ah-btn\" onclick=\"wcPlay(this)\">看看大家可能怎麼說</button><div class=\"wc-add\" style=\"display:none\">＋ 同學的回答：<input onkeydown=\"event.stopPropagation();wcAdd(this,event)\" placeholder=\"打字後按 Enter\"></div></div><div class=\"ah-step\"><div class=\"ah-ask\"><span class=\"ah-k\">再想一層</span>如果孔子現在問你：「如或知爾，則何以哉？」你會怎麼回答？<small>不是終身決定，寫下現在的版本就好。</small></div><div class=\"ah-fill\">我現在很確定：我想＿＿＿＿＿＿。<br>我有興趣，但還不確定：我喜歡＿＿＿＿＿＿。<br>我還不知道：我最近願意試試看＿＿＿＿＿＿。<br>我希望未來可以＿＿＿＿＿＿。<br>我不希望＿＿＿＿＿＿。</div></div><div class=\"ah-step ah-end\"><div class=\"ah-ask\"><span class=\"ah-k\">小結</span>你不用現在就知道這輩子要成為誰；先說說看，你現在想往哪裡走——這就是「各言爾志」。</div></div><button class=\"ah-next\" onclick=\"ahNext(this)\">下一步 ▸</button></div>"},{"label":"課後引導·⑦未來的路","head":"課後引導⑦　未來的路：畢業以後，可以往哪裡走？","body":"<div class=\"ah\"><div class=\"mm\"><div class=\"mm-side mm-l\"><ul><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">冷凍空調科</span><ul><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">這一科裡，我最喜歡做什麼？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">動手接管線、配線</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">把壞掉的機器修好</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">看懂電路和系統</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">算冷氣要多大才夠</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">升學可以去哪？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">統測：電機與電子群・電機類</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">科大：電機、能源與冷凍空調等系</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">想當老師：冷凍空調師資相關系組</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">可以考什麼證照？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">冷凍空調裝修 丙級</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">→ 乙級</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">→ 冷凍空調工程技師（國家考試）</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">可以做什麼工作？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">空調安裝、維修</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">冷凍冷藏、冷鏈物流</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">大樓機電</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">半導體、科技廠廠務</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">公營事業（考試進入）</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">累積經驗後自行創業</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">家人期待什麼？我想要什麼？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">穩定？升學？離家近？</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">我喜歡動手修？還是設計系統？</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">可以先就業再進修，也可以先升學</span></li></ul></li></ul></li></ul></div><div class=\"mm-c\">我們的路<br><small>先點自己的科別</small></div><div class=\"mm-side mm-r\"><ul><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">建築科</span><ul><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">這一科裡，我最喜歡做什麼？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">畫圖、設計空間</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">做模型</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">到工地看房子蓋起來</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">用電腦建模</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">升學可以去哪？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">統測：土木與建築群</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">科大：建築、土木、室內設計</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">營建、測量、消防等系</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">可以考什麼證照？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">建築製圖應用</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">工地主任：營造工程管理甲級，或畢業後五年工程經驗＋受訓</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">建築師、土木技師：大學＋國家考試</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">可以做什麼工作？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">事務所繪圖（CAD、BIM）</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">室內設計</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">營造工地：監工 → 工地主任</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">測量</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">公職（土木、建築類）</span></li></ul></li><li class=\"mm-n has\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">家人期待什麼？我想要什麼？</span><ul><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">穩定？升學？考公職？</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">我喜歡畫圖設計？還是在現場帶工程？</span></li><li class=\"mm-n\"><span class=\"mm-k\" onclick=\"mmTap(this,event)\">證照和經驗可以一路累積</span></li></ul></li></ul></li></ul></div></div><div class=\"mm-note\">升學管道、證照級別與報考資格每年可能調整，以當年度簡章與主管機關公告為準。</div></div>"},{"label":"延伸·盍各言爾志","head":"延伸閱讀：另一次「言志」——〈公冶長〉","body":"<div class='sp-anc'><span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">顏淵<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">顏回，字子淵，魯國人，屬孔門四科十哲的德行科。孔子贊許他好學、不遷怒、不貳過，能安貧樂道。</span></span>、<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">季路<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">仲由，字子路，一字季路，魯國人，屬孔門四科十哲的政事科。性格直率，好勇，有政事之才。</span></span><span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">侍<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">在旁邊陪伴。</span></span>。子曰：「<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">盍<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">何不。</span></span>各言<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">爾<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">你，你們。</span></span>志？」子路曰：「<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">願<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">希望、期待。</span></span>車、馬、衣、<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">輕裘<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">輕暖的皮衣。</span></span>，與朋友共。<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">敝<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">毀壞。</span></span>之而無<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">憾<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">遺憾。</span></span>。」顏淵曰：「願無<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">伐善<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">誇耀自我的才能。伐，誇耀。</span></span>，無<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">施勞<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">張揚自我的功勞。施，張揚。</span></span>。」子路曰：「願聞子之志。」子曰：「<span class=\"hg-m\" onclick=\"if(!event.target.closest('.tp-g'))this.classList.toggle('show')\"><span class=\"hg-p\">(</span>老者<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">安<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">使……得到安適的奉養，此作動詞用。</span></span>之，朋友<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">信<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">使……誠信相待，此作動詞用。</span></span>之，少者<span class=\"tp-g\" onclick=\"tpTogglePop(this,event)\">懷<span class=\"tp-gd\" onclick=\"event.stopPropagation()\">使……得到關懷愛護，此作動詞用。</span></span>之<span class=\"hg-p\">)</span><span class=\"hg-mk\">句意</span><span class=\"hg-md\">孔子關懷眾生的態度同於孟子所言：「老吾老，以及人之老；幼吾幼，以及人之幼。」皆體現高度的仁德。與《禮記》：「老有所終，壯有所用，幼有所長，鰥寡孤獨廢疾者皆有所養。」的社會福利理念亦相近。【101統測】</span></span>。」<div class=\"hg-src\">《論語・公冶長》</div></div><br><br><div class=\"tp-abox\" onclick=\"this.classList.toggle('show')\"><div class=\"tp-acov\">點此顯示語譯</div><div class=\"tp-a\"><span class=\"tp-ak\">譯</span><div class=\"tp-atext\">顏淵及子路在孔子旁邊陪伴。孔子說：「何不各自談談你們的志願呢？」子路說：「我希望把自己的車子、馬匹、衣服、輕暖的皮衣，與朋友共享，毀壞了也不會覺得遺憾。」顏淵說：「我希望不誇耀自己的才能，不張揚自己的功勞。」子路說：「我們也希望聽聽老師的志願。」孔子說：「我希望能使老年人得到安適的奉養，使朋友間誠信相待，使少年人得到關懷愛護。」</div></div></div><br><b>想一想</b><br>1. 子路在這裡的志向是什麼？和〈侍坐〉的志向比，有什麼不同？各流露出什麼個性？<div class=\"tp-abox\" onclick=\"this.classList.toggle('show')\"><div class=\"tp-acov\">點此顯示參考答案</div><div class=\"tp-a\"><span class=\"tp-ak\">答</span><div class=\"tp-atext\">這裡子路願把車子、馬匹、衣服、輕暖的皮衣和朋友共用，用壞了也不遺憾——談的是個人與朋友分享財物，看得出他<b>輕財好義、心胸開闊、樂於分享</b>。〈侍坐〉裡他「率爾而對」，志在治理千乘之國，「可使有勇，且知方」，談的是治國；兩處都看得出他率直豪爽、不拘小節。</div></div></div>2. 顏淵的志向流露出什麼個性？<div class=\"tp-abox\" onclick=\"this.classList.toggle('show')\"><div class=\"tp-acov\">點此顯示參考答案</div><div class=\"tp-a\"><span class=\"tp-ak\">答</span><div class=\"tp-atext\">「願無伐善，無施勞」：不誇耀自己的長處，不張揚自己的功勞——流露出<b>仁德謙虛</b>的個性，重視自身的修養。</div></div></div>3. 孔子的志向是什麼樣的志向？和他讚許曾皙，有沒有相通的地方？<div class=\"tp-abox\" onclick=\"this.classList.toggle('show')\"><div class=\"tp-acov\">點此顯示參考答案</div><div class=\"tp-a\"><span class=\"tp-ak\">答</span><div class=\"tp-atext\">讓老人安樂、朋友信任、年輕人得到關懷——超越個人修為、<b>以天下為己任</b>的大我（淑世）理想，呈現孔子心目中的理想世界。和讚許曾皙相通：曾皙描繪的是天下治理好之後，人民安定和樂的景象，正是孔子嚮往的理想世界。</div></div></div>"},{"label":"練習·四科十哲","head":"孔門四科十哲（填空，點空格顯示答案）","body":"<table class=\"ly-table\"><thead><tr><th><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">德行</span></span></th><th>言語</th><th>政事</th><th>文學</th></tr></thead><tbody><tr><td>顏回</td><td>宰我</td><td>冉有</td><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">子游</span></span></td></tr><tr><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">閔子騫</span></span></td><td></td><td></td><td></td></tr><tr><td>冉伯牛</td><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">子貢</span></span></td><td><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">子路</span></span></td><td>子夏</td></tr><tr><td>仲弓</td><td></td><td></td><td></td></tr></tbody></table>"},{"label":"延伸·孔子之為人（一）","head":"孔子之為人（一）：替四類選文下標題","body":"老師把選文分成四類，請為每一類想一個總括孔子個性的標題，並說明理由。<br><br><b class='dz-h'>第一類</b><br><br><div class='sp-anc'>子之燕居，申申如也，夭夭如也。（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子平常在家時，「申申如也」，很舒展，不是一天到晚皺起眉頭在憂愁，他休養的很好，非常爽朗舒展；「夭夭如也」而且活潑愉快。</div><br><br><div class='sp-anc'>子溫而厲，威而不猛，恭而安。（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子溫和而嚴肅，威嚴而不剛猛，謙恭而安適。</div><br><br><div class='sp-anc'>子絕四：毋意，毋必，毋固，毋我。（〈子罕〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子沒有的四種心：一、不妄加猜測、臆度；二、不武斷、專制；三、沒有固執己見；四、不自私、不求一己之利。</div><br><br><b class='dz-h'>第二類</b><br><br><div class='sp-anc'>子之所慎：齊，戰，疾。（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子最謹慎小心對待的有：祭祀前的齋戒，戰爭，疾病。</div><br><br><div class='sp-anc'>子不語怪，力，亂，神。（〈述而〉）</div><br><br><div class='sp-anc'>季路問事鬼神。子曰：「未能事人，焉能事鬼？」敢問死。曰：「未知生，焉知死？」（〈先進〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>季路問如何侍奉鬼神。孔子說：「還沒能好好侍奉人，如何能侍奉鬼呢？」季路說：「請問死是怎麼回事？」孔子說：「還沒弄清楚生，如何知道死呢？」</div><br><br><div class='sp-anc'>孔子於鄉黨，恂恂如也，似不能言者。其在宗廟朝廷，便便言，唯謹爾。（〈鄉黨〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子在自己的鄉里，顯得很溫和恭敬，像是不會說話的樣子。但他在宗廟裡、朝廷上，卻說話清楚明暢、很善於言辭，只是同時保持謹慎態度啊。</div><br><br><b class='dz-h'>第三類</b><br><br><div class='sp-anc'>子與人歌而善，必使反之，而後和之。（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子和別人一起唱歌，如果別人唱得好，就必定要他再唱，然後自己跟著唱。</div><br><br><div class='sp-anc'>子食於有喪者之側，未嘗飽也。子於是日哭，則不歌。（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>有戴孝人在旁時，孔子從未吃飽過。孔子在這一天弔喪哭泣，則當日不再歌唱。</div><br><br><b class='dz-h'>第四類</b><br><br><div class='sp-anc'>廄焚。子退朝，曰：「傷人乎？」不問馬。（〈鄉黨〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>馬廄燒了。孔子退朝回來，問：「傷人了嗎？」不問馬的情況。</div><br><br><div class='sp-anc'>子釣而不綱，弋不射宿。（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子釣魚時不用網撈捕，射箭時不射棲息的鳥。</div><br><br><b>難字</b>　燕居：閒居在家。申申、夭夭：舒展、和樂的樣子。意：臆測。必：武斷。固：固執。我：自私。齊：同「齋」，祭祀前的齋戒。恂恂：溫和恭順。便便：說話明白流暢。反：再唱一次。綱：用大繩橫斷水流、掛網捕魚。弋：用繫著絲繩的箭射鳥。宿：歸巢棲息的鳥。<br>"},{"label":"延伸·孔子之為人（二）","head":"孔子之為人（二）：孔子怎麼說自己","body":"<div class='sp-anc'>子曰：「德之不脩，學之不講，聞義不能徙，不善不能改，是吾憂也。」（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：「不能修養品德，不鑽研學問，聽到道義之事不能跟著做，有錯誤不能改正，這些都是我的憂慮。」</div><br><br><div class='sp-anc'>子曰：「默而識之，學而不厭，誨人不倦，何有於我哉？」（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：「將知識默記在心，學習時，不感到滿足；教人時，不感到疲倦，對我來說沒什麼問題。」</div><br><br><div class='sp-anc'>葉公問孔子於子路，子路不對。子曰：「女奚不曰，其為人也，發憤忘食，樂以忘憂，不知老之將至云爾。」（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>葉公問子路：孔子是怎樣的人，子路不知如何回答。孔子說：「你怎麼不說：他這個人啊，發憤學習就忘記吃飯，高興起來就忘記了憂愁，不知道快要變老了？」</div><br><br><div class='sp-anc'>子曰：「我非生而知之者，好古，敏以求之者也。」（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：我不是天生就有學問的，只是個喜歡讀書、勤勉地追求知識的人。</div><br><br><div class='sp-anc'>子曰：「若聖與仁，則吾豈敢？抑為之不厭，誨人不倦，則可謂云爾已矣。」公西華曰：「正唯弟子不能學也。」（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：「如果說我是聖人、仁者，我怎麼敢當？不過說我在這方面不厭倦地學，不懈怠地教人，倒還可說是這樣吧！」公西華說：「這正是弟子們所學不到的呀！」</div><br><br><div class='sp-anc'>子曰：「出則事公卿，入則事父兄，喪事不敢不勉，不為酒困，何有於我哉？」（〈子罕〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：「在外事奉公卿，在家孝敬父兄，有喪事不敢不盡力去辦，不被酒所困，這些事對我來說有什麼困難呢？」</div><br><br><div class='sp-anc'>子曰：「君子道者三，我無能焉：仁者不憂，知者不惑，勇者不懼。」子貢曰：「夫子自道也。」（〈憲問〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：「君子有三種美德，我都未能做到：仁者不憂慮，智者不疑惑，勇者不畏懼。」子貢說：「這是老師自謙之言啊！」</div><br><br><div class='sp-anc'>子曰：「飯疏食飲水，曲肱而枕之，樂亦在其中矣。不義而富且貴，於我如浮雲。」（〈述而〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>孔子說：「吃粗食、喝白水、彎著胳膊當枕頭，喜樂也在其中了！缺少仁義的富貴，對我來說，就像天上的浮雲。」</div><br><br><div class='sp-anc'>子貢曰：「有美玉於斯，韞匵而藏諸？求善賈而沽諸？」子曰：「沽之哉！沽之哉！我待賈者也。」（〈子罕〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>子貢說：「假如這有塊美玉，是用櫃子藏起來呢？還是賣給識貨的人呢？」孔子說：「賣了它！賣了它！我等著識貨的人。」</div><div class='kz-note'>「沽之」比喻出來做事，不把才華藏起來。</div><br><br><b>想一想</b>　孔子自述的個性有哪些？哪一則最打動你？<br>"},{"label":"延伸·孔子之為人（三）","head":"孔子之為人（三）：別人眼中的孔子","body":"<b class='dz-h'>隱者看孔子</b><br><br><div class='sp-anc'>子路宿於石門。晨門曰：「奚自？」子路曰：「自孔氏。」曰：「是知其不可而為之者與？」（〈憲問〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>子路在石門睡覺，看門的說：「你從哪來？」子路答：「從孔子那裏來。」問：「是那個明知做不到卻還要去做的人嗎？」</div><br><br><div class='sp-anc'>長沮、桀溺耦而耕，孔子過之，使子路問津焉。長沮曰：「夫執輿者為誰？」子路曰：「為孔丘。」曰：「是魯孔丘與？」曰：「是也。」曰：「是知津矣。」問於桀溺，桀溺曰：「子為誰？」曰：「為仲由。」曰：「是魯孔丘之徒與？」對曰：「然。」曰：「滔滔者天下皆是也，而誰以易之？且而與其從辟人之士也，豈若從辟世之士哉？」耰而不輟。子路行以告。夫子憮然曰：「鳥獸不可與同群，吾非斯人之徒與而誰與？天下有道，丘不與易也。」（〈微子〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>長沮、桀溺一起耕田，孔子路過，讓子路詢問渡口。長沮說：「駕車人是誰？」子路說：「是孔丘。」「是魯國孔丘嗎？」「是。」「那他應該知道渡口在那裏。」子路再問桀溺。桀溺說：「你是誰？」「我是仲由。」「是魯國孔丘的學生嗎？」「是。」「天下如洪水氾濫般大亂，誰和你們去改變？你與其跟隨躲避壞人的人（孔子當時被壞人包圍），哪裏比得上跟隨我們這些避世的人呢？」他邊說邊不停地播種。子路回來告訴孔子，孔子失望地說：「人不能和鳥獸同群，我不跟世人在一起，要跟誰在一起呢？天下太平，我就用不著提倡改革了。」</div><div class='kz-note'>孔子不肯避世：正因為天下無道，才要出來改變它。</div><br><br><b class='dz-h'>學生看老師</b><br><br><div class='sp-anc'>顏淵喟然歎曰：「仰之彌高，鑽之彌堅；瞻之在前，忽焉在後。夫子循循然善誘人，博我以文，約我以禮。欲罷不能，既竭吾才，如有所立卓爾。雖欲從之，末由也已。」（〈子罕〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>顏淵感嘆地說：「仰望老師的形象越來越覺得高大，鑽研老師的學問越來越感到堅實。眼看就在前面，忽然又在後邊。老師循序漸進善於誘導學生，用典籍文章來豐富我們的知識，用禮儀道德來規範我們的言行，使得我們想停止學習都不可能。即使竭盡我們的才智，而老師的道卻依然高高聳立在我們的面前，雖然想要繼續追隨上去，但是卻無法追得上。」</div><br><br><div class='sp-anc'>叔孫武叔毀仲尼。子貢曰：「無以為也，仲尼不可毀也。他人之賢者，丘陵也，猶可踰也；仲尼，日月也，無得而踰焉。人雖欲自絕，其何傷於日月乎？多見其不知量也！」（〈子張〉）</div><button type='button' class='sp-trans-toggle' onclick='spTransTog(this)'>▸ 顯示語譯</button><div class='sp-trans-body'>叔孫武叔誹謗仲尼。子貢說：「（這樣做）是沒有用的！仲尼是毀謗不了的。別人的賢德好比丘陵，還可超越過去，仲尼的賢德好比太陽和月亮，是無法超越的。雖然有人要自絕於日月，對日月又有甚麼損害呢？只是表明他不自量力而已。」</div><br><br><b>想一想</b><br>1. 隱者怎麼評論孔子？孔子怎麼回應？（可對照〈侍坐〉：孔子為什麼「喟然嘆」？）<br>2. 顏淵怎麼形容老師？子貢用什麼比喻孔子？<br>3. 影響你最深的老師是誰？你會怎麼形容他？<br>"}], "lead": {"label": "課前·引導動機", "head": "課前引導", "body": "<b>學習重點</b><br>一、認識孔子的思想人格與《論語》的價值。<br>二、體會孔子培育人才的苦心和禮樂治國的真諦。<br>三、學習從言談舉止分析人物的性格與形象。<br>四、檢視自我能力，培養志趣與專長。<br><br><b>討論問題</b><br>· 你認為過去的「經典」之於現代，有什麼意義呢？<br>· 宋人趙普曾說「半部論語治天下」，若要你選出一本書來「治天下」，你會選擇哪一本呢？為什麼？"}, "appreciation": [{"label": "賞析", "head": "賞析（一）全文概述與層次", "body": "《論語》的篇章大多是文字簡短的語錄片段，本文是全書最長的篇章，記敘完整，涉及的人物眾多且個性鮮明，是呈現孔門教學情景最具代表性的一篇。<br><br>本文可分三個層次。從開頭至「則何以哉」寫孔子問志。從「子路率爾而對」至「吾與點也」寫弟子言志。從「三子者出」至文末，寫孔子評志。「志」是貫穿全文的核心，透過弟子「言志」來表現孔子「治國以禮」的中心思想，脈絡十分清楚。"}, {"label": "賞析", "head": "賞析（二）場景安排", "body": "文中場景的安排別具巧思：先以「侍坐」點出日常的生活場景，呈現師生間輕鬆和諧的氛圍；接著寫曾皙「鼓瑟希」，這才發現原來全場對話，從一開始便是在充滿音樂的美好情境中進行的；最後當「三子者出，曾皙後」，對話者從五人變成二人，展現文章繁簡疏密的變化，使情節充滿張力。"}, {"label": "賞析", "head": "賞析（三）人物刻畫", "body": "狀寫人物則靈動傳神：例如「率爾」之詞一出，子路形貌聲口立即如在眼前。曾皙開口前「鼓瑟希，鏗爾，舍瑟而作」，一連串細膩又連貫的動作，暗示曾皙與眾不同，其重要性比前三者也略勝一籌。寫孔子「喟然而嘆」，則使文章留下深長的況味。<br><br>文以對話形式精彩呈現師生的互動，人物的性情一覽無遺：子路的粗率豪邁，與冉有、公西華的謙恭謹慎恰成對比。當灑脫而自在的曾皙回答：「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸。」這充滿詩意場景的理想境界，把全文推至最高潮。而孔子「吾與點也」的讚賞，既展現長者的風範，也隱約寄寓對禮樂教化、清平盛世的期待。"}]}, "keyRhetoric": [{"name": "倒裝", "pages": [{"sub": "先看懂：什麼是倒裝？", "body": "<div class=\"dz-box\"><p><b>倒裝</b>：字的順序跟我們現在說話不一樣。只要把字<b>搬回原位</b>，就看得懂。</p><p>先認識句子的三個角色，<b>跟英文文法一樣</b>：</p><table class=\"dz-svo\"><tr><th>國文說</th><th>英文說</th><th>意思</th><th>I love you.</th><th>我愛你。</th></tr><tr><td class=\"dz-s\">主語</td><td class=\"dz-s\">主詞 S</td><td>誰在做</td><td class=\"dz-s\">I</td><td class=\"dz-s\">我</td></tr><tr><td class=\"dz-v\">述語</td><td class=\"dz-v\">動詞 V</td><td>做什麼</td><td class=\"dz-v\">love</td><td class=\"dz-v\">愛</td></tr><tr><td class=\"dz-o\">賓語</td><td class=\"dz-o\">受詞 O</td><td>做在誰／什麼身上</td><td class=\"dz-o\">you</td><td class=\"dz-o\">你</td></tr></table><p><b>賓語前置</b>＝受詞跑到動詞前面。<br>例：知<b>吾</b>＝了解<b>我</b>（knows <b>me</b>），古文卻寫成「不<b>吾</b>知」，就像英文說成 Nobody <b>me</b> knows。</p><p>本課有兩種：① 否定句（有「不、毋」）＋受詞是「吾、爾」這類代名詞　② 問句＋受詞是「何」這類疑問詞</p></div><div class=\"dz-leg\"><span class=\"dz-o\">紅字</span>＝被搬到前面的字　<span class=\"dz-v\">藍字</span>＝它本來應該跟在誰後面</div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t\" style=\"--d:0\">不</span><span class=\"dz-t dz-o\" style=\"--d:1\">吾</span><span class=\"dz-t dz-v\" style=\"--d:-1\">知</span><span class=\"dz-t\" style=\"--d:0\">也</span></div><div class=\"dz-eq\">不吾知也　→　不知吾也</div><div class=\"dz-tr\">白話：沒有人了解我</div></div>"}, {"sub": "① 否定句：賓語跑到前面", "body": "<div class=\"dz-rule\">有「不、毋」＋賓語是「吾（我）」→「吾」搬到前面<br><span class=\"dz-en\">英文類比：Nobody knows <b>me</b>. → 古文像說成 Nobody <b>me</b> knows.</span></div><div class=\"dz-leg\"><span class=\"dz-o\">紅字</span>＝被搬到前面的字　<span class=\"dz-v\">藍字</span>＝它本來應該跟在誰後面</div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t\" style=\"--d:0\">不</span><span class=\"dz-t dz-o\" style=\"--d:1\">吾</span><span class=\"dz-t dz-v\" style=\"--d:-1\">知</span><span class=\"dz-t\" style=\"--d:0\">也</span></div><div class=\"dz-eq\">不吾知也　→　不知吾也</div><div class=\"dz-tr\">白話：沒有人了解我</div></div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t\" style=\"--d:0\">毋</span><span class=\"dz-t dz-o\" style=\"--d:1\">吾</span><span class=\"dz-t dz-v\" style=\"--d:-1\">以</span><span class=\"dz-t\" style=\"--d:0\">也</span></div><div class=\"dz-eq\">毋吾以也　→　毋以吾也</div><div class=\"dz-tr\">白話：不要因為我（年紀比較大）就不敢說</div></div>"}, {"sub": "② 問句：疑問詞跑到前面", "body": "<div class=\"dz-rule\">問句裡的「何」（什麼、怎樣）是賓語 →「何」搬到前面<br><span class=\"dz-en\">英文也一樣！You use <b>what</b>? → <b>What</b> do you use? 疑問詞 what 也跑到最前面。</span></div><div class=\"dz-leg\"><span class=\"dz-o\">紅字</span>＝被搬到前面的字　<span class=\"dz-v\">藍字</span>＝它本來應該跟在誰後面</div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t\" style=\"--d:0\">則</span><span class=\"dz-t dz-o\" style=\"--d:1\">何</span><span class=\"dz-t dz-v\" style=\"--d:-1\">以</span><span class=\"dz-t\" style=\"--d:0\">哉</span></div><div class=\"dz-eq\">則何以哉　→　則以何哉</div><div class=\"dz-tr\">白話：那要用什麼來表現呢？</div></div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t\" style=\"--d:0\">爾</span><span class=\"dz-t dz-o\" style=\"--d:1\">何</span><span class=\"dz-t dz-v\" style=\"--d:-1\">如</span></div><div class=\"dz-eq\">爾何如　→　爾如何</div><div class=\"dz-tr\">白話：你怎麼樣呢？</div></div>"}, {"sub": "③ 其他倒裝", "body": "<div class=\"dz-rule\">不是賓語前置，但順序也和現在說話不同，一樣搬回原位就懂</div><div class=\"dz-leg\"><span class=\"dz-o\">紅字</span>＝被搬到前面的字　<span class=\"dz-v\">藍字</span>＝它本來應該跟在誰後面</div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t dz-o\" style=\"--d:3\">一</span><span class=\"dz-t dz-o\" style=\"--d:3\">日</span><span class=\"dz-t dz-v\" style=\"--d:-2\">長</span><span class=\"dz-t dz-v\" style=\"--d:-2\">乎</span><span class=\"dz-t dz-v\" style=\"--d:-2\">爾</span></div><div class=\"dz-eq\">一日長乎爾　→　長乎爾一日</div><div class=\"dz-tr\">白話：比你們年長一點點</div></div><div class=\"dz-ex\"><div class=\"dz-lab\"><span class=\"dz-l1\">課文原句</span><span class=\"dz-l2\">搬回原位</span></div><div class=\"dz-row\"><span class=\"dz-t\" style=\"--d:0\">使</span><span class=\"dz-t dz-o\" style=\"--d:1\">足</span><span class=\"dz-t dz-v\" style=\"--d:-1\">民</span></div><div class=\"dz-eq\">使足民　→　使民足</div><div class=\"dz-tr\">白話：讓人民富足</div></div>"}]}], "handoutV2": [{"title": "一、作者與題解", "page": "P.64-65", "blocks": [["text", "mj", "壹　課文重點整理"], ["table", "", [["萬世師表、至聖先師──孔子"], ["字號", "孔子名丘，字仲尼"], ["時代", "<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">春秋</span></span>魯國　陬邑（今山東省　曲阜市）人"], ["生平<br>及<br>成就", "年少貧賤，濡染周禮<br>父親叔梁紇，母親顏徵在。孔子兒時玩遊戲常常擺設俎豆等祭器，模仿祭禮動作，深受周禮薰陶。十九歲結婚，生子孔鯉，為了謀生他先後做過「委吏」、「乘田」。成年後的孔子回憶這段生活時曾感嘆的說：「吾少也賤，故多能鄙事。」（論語　子罕）<br>好學善問，有教無類<br>孔子十五歲志於學，學習內容以詩、書、禮、樂為主，曾向郯子學官制，向老子問禮，向師襄學琴，向萇弘問古樂。孔子首開平民教育之風，主張「有教無類」，只要備「束脩（十條乾肉）」之禮，就可以跟隨他學習<br>去魯至齊，接淅去齊<br>孔子三十五歲時，季孫氏專政且僭越，魯國禮壞樂崩，孔子因此不願繼續待在魯國，便帶著弟子前往齊國，期望施展抱負。孟子　萬章下記載：「孔子之去齊，接淅而行（形容時間急迫，匆忙離去）。」（語譯：孔子在淘米做飯時倉皇離開齊國，拎起還沒來得及瀝乾的米便匆匆趕路。）<br>周遊列國，坎坷流轉<br>孔子周遊列國，欲推行仁政、德政的主張，懷抱著「知其不可為而為之」的理想，堅持一貫的理念。孔子歷盡艱辛，四處遊說，宣揚政治理想終未能實現<br>世衰道微，整理六經<br>孔子對「六經」的整理，無疑是他對中華文化最大的貢獻。司馬遷曰：「孔子擔憂王道廢弛、邪道興起，於是論定編次詩、書，修訂振興禮、樂。」（史記　儒林列傳）孟子則說：「世衰道微，邪說暴行有作。臣弒其君者有之，子弒其父者有之。孔子懼，作<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">春秋</span></span>。」（孟子　滕文公下）（語譯：世道衰微，錯誤的學說與暴虐的行為又再度興起。臣子殺害國君的事發生了，兒子殺害父親的事也發生了。孔子非常害怕擔心，便整理了春秋這本史書。）"]]], ["table", "", [["其他", "至聖：<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">孔子</span></span><br>亞聖：<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">孟子</span></span>", "復聖：顏回<br>述聖：子思", "宗聖：曾參"]]], ["table", "", [["選錄<br>篇章", "本文選自論語 先進，原文無標題，標題乃編者所訂。論語各章多為簡要語錄，然而本章卻超過四百字，結構完整，人物形象鮮明，在論語中極為特出<br>全文記錄孔子與學生的日常對話。從孔子引導學生暢談志向，看出學生的政治抱負及人格特質。其中孔子對曾皙的讚許，更透露出儒家淑世的精神與期許世界大同的襟懷"]]]]}, {"title": "二、國學常識　(一)文體簡介——語錄體", "page": "P.65", "blocks": [["text", "para", "1.體例：「語錄體」是指直接記錄或摘錄言論的一種文體。中國古代散文中，尚書主要是記言散文，至春秋　戰國，哲人學者或聚眾講學，或與時人辯論，由其弟子加以記錄，匯集成篇，遂成語錄體著作，論語尤為典範。"], ["text", "para", "2.影響：繼論語之後，孟子、墨子、莊子、荀子、韓非子亦偶見語錄。漢代　揚雄的法言、隋代　王通的中說，文字和體裁都有意模仿論語。論語語錄體對後世的影響，還及於世說新語之類的筆記小說。"], ["text", "para", "3.著作：「語錄」此名稱至唐代方才出現。唐代　孔思尚有宋齊語錄十卷，為「語錄」稱謂之始。唐代僧人講佛，弟子往往直錄其語，沿稱「語錄」。至於宋代理學家傳道講學，弟子加以記錄整理，亦成語錄書，如：程顥、程頤　二程粹言、朱熹　朱子語類。明代　王陽明　傳習錄亦採語錄體。"]]}, {"title": "(二)「論語」簡介", "page": "P.65", "blocks": [["table", "", [["作者", "孔子弟子及再傳弟子"], ["文體", "記載孔子應答弟子及時人的對話，是一部<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">語錄體</span></span>經典。"], ["篇章", "共二十篇，始於<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">學而</span></span>，終於<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">堯曰</span></span><br>前十篇稱為「上論」，後十篇稱為「下論」。每篇篇名，均各取首章首句去除「子曰」、「孔子」後之二、三字為篇名，篇名與篇中各則涵義不盡相關"], ["內容", "以<span class=\"jy-cir\">④</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">仁</span></span>為中心，<span class=\"jy-cir\">⑤</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">忠、恕</span></span>為行仁的方法"], ["備註", "南宋　朱熹將論語與<span class=\"jy-cir\">⑥</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">孟子</span></span>、<span class=\"jy-cir\">⑦</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">大學</span></span>、<span class=\"jy-cir\">⑧</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">中庸</span></span>合為「四書」"]]]]}, {"title": "(三)孔門「四科十哲」", "page": "P.66-67", "blocks": [["text", "para", "（論語　先進）子曰：「從我於陳、蔡者，皆不及門也。」德行：顏淵、閔子騫、冉伯牛、仲弓。言語：宰我、子貢。政事：冉有、季路。文學：子游、子夏。分述整理如下："], ["text","html","<div class=\"hd-tw\"><table class=\"jy-table jy-cols-4 hd-table\" data-merged=\"1\"><tr><th class=\"jy-th\">科別</th><td>人名</td><td>字號</td><td>相關事蹟</td></tr><tr><th class=\"jy-th\" rowspan=\"4\">德行</th><td>顏回</td><td>子淵</td><td>子曰：「賢哉回也！一簞食，一瓢飲，在陋巷。人不堪其憂，回也不改其樂。賢哉回也！」 （論語 雍也）<br>語譯：孔子說：「多麼賢良啊顏回！吃的是一小簍飯，喝的是一瓢湯水，住在陋巷裡。別人忍受不了這種貧苦，而顏回卻不改變他好學的樂趣。多麼賢良啊顏回！」<br>安貧樂道，「其心三月不違仁。」<br>語譯：他的內心長久不背離仁德。<br>不遷怒，不貳過。<br>語譯：不把憤怒移轉到無關的人身上，不犯同樣的過失。</td></tr><tr><td>閔損</td><td>子騫</td><td>子曰：「孝哉閔子騫！人不間於其父母昆弟之言。」 （論語　先進）<br>語譯：孔子說：「真是孝順啊閔子騫！人們對他父母兄弟稱讚他孝順友愛的話，都沒有異議。」</td></tr><tr><td>冉耕</td><td>伯牛</td><td>伯牛有疾，子問之，自牖執其手，曰：「亡之，命矣夫！斯人也而有斯疾也！斯人也而有斯疾也！」 （論語 雍也）<br>語譯：冉伯牛得了惡疾，孔子前往探視慰問，從窗戶外抓著他的手，說：「沒有得到這種病的道理，這是天命的關係啊！這樣有德行的人，卻得到這種病！這樣有德行的人，卻得到這種病呀！」</td></tr><tr><td>冉雍</td><td>仲弓</td><td>出身微賤，勤奮向學。<br>子謂仲弓曰：「犁牛之子騂且角，雖欲勿用，山川其舍諸？」<br>（論語　雍也）<br>語譯：孔子談論到仲弓說：「一頭毛色駁雜的牛所生的小牛，毛色純赤且兩角端正，人們雖然不想用牠來作犧牲祭品，但是山川的神明哪裡會捨棄牠呢？」</td></tr><tr><th class=\"jy-th\" rowspan=\"2\">言語</th><td>宰予</td><td>子我</td><td>宰予晝寢。子曰：「朽木不可雕也，糞土之牆不可杇也，於予與何誅！<br>（論語　公冶長）<br>語譯：宰予白天睡覺。孔子說：「腐朽的木頭不可以用來雕刻，用汙穢的泥土築成的牆無法加以粉刷，對於宰予這樣的人，我還有什麼好責備的！」</td></tr><tr><td>端木賜</td><td>子貢</td><td>曾仕於衛、魯，游說於齊、吳等國，聞名諸侯，經商於曹、魯之間。<br>賜不受命，而貨殖焉，億則屢中。 （論語 先進）<br>語譯：子貢不相信命運，經商致富，臆測常常猜中。</td></tr></table></div>"], ["text","html","<div class=\"hd-tw\"><table class=\"jy-table jy-cols-4 hd-table\" data-merged=\"1\"><tr><th class=\"jy-th\" rowspan=\"2\">政事</th><td>冉求</td><td>子有</td><td>個性謙退，孔子曾說：「求也退，故進之。」<br>語譯：冉求為人退縮，所以鼓勵他進取。<br>曾為季氏宰，為季氏聚斂，孔子斥責曰：「非吾徒也。小子鳴鼓而攻之，可也。」 （論語 先進）<br>語譯：冉求不是我的門徒。弟子們鳴鼓來聲討他，是可以的。</td></tr><tr><td>仲由</td><td>子路（季路）</td><td>為人直率魯莽，好勇力。<br>子曰：「道不行，乘桴浮於海，從我者其由與。」子路聞之喜。子曰：「由也，好勇過我，無所取材。」 （論語 公冶長）<br>語譯：孔子說：「我的理想不能實行，不如乘著木筏漂流到海外去，能夠跟隨我的大概只有仲由吧。」子路聽了很高興。孔子就說：「仲由啊，你比我還勇敢，但我還沒找到製作木筏的材料。」</td></tr><tr><th class=\"jy-th\" rowspan=\"2\">文學</th><td>言偃</td><td>子游</td><td>子之武城，聞弦歌之聲。夫子莞爾而笑，曰：「割雞焉用牛刀？」子游對曰：「昔者偃也聞諸夫子曰：『君子學道則愛人，小人學道則易使也。』」 （論語　陽貨）<br>語譯：孔子到武城，聽見彈琴唱歌的聲音。孔子微笑，說：「殺雞哪裡要用到牛刀呢？」子游回答道：「從前我聽老師說過：『在上位的人學了禮樂就能體恤人民，平民百姓學了禮樂就容易遵從政令。』」</td></tr><tr><td>卜商</td><td>子夏</td><td>子曰：「起予者商也！始可與言詩已矣。」 （論語 八佾）<br>語譯：啟發我的人是卜商呀！現在可以和他討論詩經了。</td></tr></table></div>"]]}, {"title": "三、課文深究　(一)文本透視鏡", "page": "P.67-68", "blocks": [["table", "", [["寫作背景", "1.孔子曾擔任小官「委吏」與「乘田」，歷時不長。年過三十，即在家設教授徒。私學的創設，打破「學在官府」的傳統，進一步促進學術文化的下移<br>2.據錢穆所著孔子傳，推論此章應該發生在孔子五十歲出仕之前<br>3.孔門講學本在用世，子路長於治軍，冉有長於理財，公西華長於外交禮節，三人所學各有專長。孔子既寄慨於一生理想未能用世，又深惜三位弟子意於進取，卻擔心他們懷才不遇，於是特別激賞放情山水、從容自樂於日常的曾皙<br>4.就本章內容而言，師生討論、言志，當是在生活比較安穩的時期，錢穆將其置於「孔子第一期之教育生涯」"]]], ["text","html","<div class=\"hd-tw\"><table class=\"jy-table jy-cols-4 hd-table\" data-merged=\"1\"><tr><th class=\"jy-th\">結構</th><td>段落</td><td>旨意</td><td>讀見真相</td></tr><tr><th class=\"jy-th\">起<br>孔子問志</th><td>第一段</td><td>孔子鼓勵各自言志</td><td>師生相處氣象。凸顯孔子和藹可親，循循善誘的長者風範</td></tr><tr><th class=\"jy-th\" rowspan=\"3\">承<br>弟子述志</th><td rowspan=\"3\">第二段<br>～<br>第四段</td><td>子路──率爾而對<br>（軍事、禮義）</td><td>「千乘之國，攝乎大國之間，加之以師旅，因之以饑饉。由也為之，比及三年，可使有勇，且知方也」<br>→希望在治國上表現軍事才能，則顯現其自負。孔子「哂之」，褒貶寓含其中</td></tr><tr><td>冉有──問而後答<br>（經濟、民生）</td><td>「方六、七十，如五、六十，求也為之，比及三年，可使足民。如其禮樂，以俟君子」<br>→冉有表示須待更賢能的君子才能實行禮義教化。呈現冉有「退」與「讓」的個性</td></tr><tr><td>公西華──問而後答<br>（外交）</td><td>「非曰能之，願學焉。宗廟之事，如會同，端章甫，願為小相焉」<br>→願做祭典中的「小相」（典禮中擔任司儀或贊禮［輔佐禮儀進行］的人）</td></tr><tr><th class=\"jy-th\">轉<br>孔子讚許<br>曾皙之志</th><td>第五段</td><td>曾皙──止瑟而答<br>（禮樂融合）</td><td>1.「莫春者，春服既成，冠者五、六人，童子六、七人，浴乎沂，風乎舞雩，詠而歸」<br>→曾皙所言乃儒家內聖外王事業完成之後，一種從容、祥和、寧靜的境界，因此深獲孔子嘉許。曾皙回溯生命的本源，呈現出人與人、人與自然和諧交融的感受<br>2.「夫子喟然嘆曰：『吾與點也！』」<br>→曾皙描繪的是在禮樂治理下的太平社會的縮影，與孔子「風清俗美、人民安樂」的政治理想正好相符</td></tr><tr><th class=\"jy-th\">合<br>孔子評志</th><td>第六段</td><td>強調<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">禮讓</span></span></td><td>1.「三子者出，曾皙後。曾皙曰：『夫三子者之言何如？』子曰：『亦各言其志也已矣。』」<br>2.「曰：『夫子何哂由也？』曰：『為國以<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">禮</span></span>，其言不讓，是故哂之。』」<br>3.「『唯求則非邦也與？』『安見方六、七十，如五、六十，而非邦也者？』」<br>4. 「『唯赤則非邦也與？』『宗廟會同，非諸侯而何？赤也為之小，孰能為之大？』」<br>→孔子認為子路言及以禮治國，自己卻毫不謙讓；冉有志向雖亦是治國大事，但其言謙讓；公西華亦然，且更謙虛。「宗廟會同」與「諸侯（之事）」皆同為政治，孔子肯定公西華的才能與謙遜。孔子的回答均針對「<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">其言不讓</span></span>」，為「是故哂之」具體說明</td></tr></table></div>"]]}, {"title": "(二)文本異世界", "page": "P.69", "blocks": [["table", "", [["主旨", "全文記錄孔子與學生的日常對話。「<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">志</span></span>」是貫穿全文的核心，透過弟子「言志」來表現孔子「治國以<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">禮</span></span>」的中心思想"], ["文體", "<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">語錄</span></span>體"], ["寫作特色", "1.人物形象鮮明，栩栩如生：子路最先搶答，且說明志向時毫不謙讓，可知其急躁自負。冉有等待君子禮樂教化、公西華表明願為小相，都可看出他們謙恭謹慎的個性。而曾皙與眾不同的嚮往，點出其灑脫真誠<br>2.因材施教、啟發引導式教學：在孔子的鼓勵之下，學生各言其志，具體描繪心中藍圖，暢所欲言，透顯出師生之間和樂融融、無話不談的交流互動。夫子「哂由」，並讚嘆曾皙充滿詩意的理想境界，隱約可看出孔子對禮樂教化、太平盛世的期待<br>3.文章脈絡清晰，結構完整：本文是論語最長的篇章，記敘完整，涉及眾多人物，為孔門教學場景留下最精彩的一頁"]]]]}, {"title": "一、形近字", "page": "P.69", "blocks": [["text", "mj", "貳　形音義比較"], ["text","html","<div class=\"hd-tw\"><table class=\"jy-table jy-cols-4 hd-table\" data-merged=\"1\"><tr><th class=\"jy-th\">形</th><td>音</td><td>義</td><td>例</td></tr><tr><th class=\"jy-th\" rowspan=\"2\">撰</th><td rowspan=\"2\">ㄓㄨㄢˋ</td><td>著述</td><td>「撰」文、「撰」稿</td></tr><tr><td>陳述</td><td>異乎二三子之「撰」</td></tr><tr><th class=\"jy-th\" rowspan=\"2\">饌</th><td rowspan=\"2\">ㄓㄨㄢˋ</td><td>吃喝</td><td>有酒食，先生「饌」 （論語 為政）</td></tr><tr><td>酒食菜餚</td><td>肴「饌」</td></tr><tr><th class=\"jy-th\" rowspan=\"2\">巽</th><td rowspan=\"2\">ㄒㄩㄣˋ</td><td>卑順、謙恭</td><td>「巽」與之言 （論語 子罕）</td></tr><tr><td>易經卦名</td><td>「巽」卦</td></tr></table></div>"]]}, {"title": "二、一字多音", "page": "P.70", "blocks": [["text","html","<div class=\"hd-tw\"><table class=\"jy-table jy-cols-4 hd-table\" data-merged=\"1\"><tr><th class=\"jy-th\">字</th><td>音</td><td>義</td><td>例</td></tr><tr><th class=\"jy-th\" rowspan=\"3\">舍</th><td rowspan=\"2\">ㄕㄜˇ</td><td>放下</td><td>鼓瑟希，鏗爾，「舍」瑟而作</td></tr><tr><td>止息、休息</td><td>逝者如斯夫！不「舍」晝夜     （論語 子罕）</td></tr><tr><td>ㄕㄜˋ</td><td>量詞。古代計算行軍里數的單位。三十里為一舍</td><td>退避三「舍」</td></tr><tr><th class=\"jy-th\" rowspan=\"7\">與</th><td rowspan=\"5\">ㄩˇ</td><td><span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">贊同、讚許</span></span></td><td>吾「與」點也</td></tr><tr><td>支持、贊助</td><td>天道無親，常「與」善人  （老子第七十九章）</td></tr><tr><td>向、對</td><td>「與」虎謀皮</td></tr><tr><td>等待</td><td>時不我「與」</td></tr><tr><td>同類</td><td>民胞物「與」</td></tr><tr><td><span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄩˊ</span></span></td><td>通「歟」，句末助詞，表達疑問、反詰、感嘆的語氣</td><td>唯赤則非邦也「與」</td></tr><tr><td><span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">ㄩˋ</span></span></td><td>參加</td><td>參「與」</td></tr></table></div>"]]}, {"title": "倒裝", "page": "P.70", "blocks": [["text", "mj", "參　修辭"], ["table", "", [["定義", "為了音律上的需要，或為引起讀者注意，強調某些語詞，刻意破壞句子原本順序，顛倒文法邏輯詞序的修辭法"], ["例句", "一日長乎爾→<span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">長乎爾一日</span></span><br>毋吾以也→<span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">毋以吾也</span></span><br>不吾知也→不知吾也<br>則何以哉→則以何哉<br>可使足民→<span class=\"jy-cir\">③</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">可使民足</span></span>"]]]]}, {"title": "一、與孔子相關的對聯", "page": "P.71", "blocks": [["text", "mj", "肆　延伸學習"], ["table", "", [["", "對聯", "出處"], ["1.", "德侔天地／道貫古今", "山東　曲阜　孔廟"], ["2.", "成春秋一書，褒貶嚴斧鉞／留洙泗片席，俎豆以馨香", "山東　曲阜　孔廟"], ["3.", "道若江河，隨地盡成洙泗／聖如日月，普天猶是春秋", "山東　樂陵　文廟"], ["4.", "觀於海者難為水／譬如天之不可階", "山西　平遙　文廟"], ["5.", "生民來，未有夫子也／知我者，其惟春秋乎", "山西　平遙　文廟"], ["6.", "道與天地參，功滿天地，名滿天地／書留春秋在，知我春秋，罪我春秋", "山西　平遙　文廟"]]]]}, {"title": "二、「論語」中的成語", "page": "P.71", "blocks": [["table", "", [["成語", "釋義", "例句"], ["巧言令色", "形容花言巧語，虛偽討好。", "看他對總經理巧言令色的樣子，真是個討厭的傢伙。"], ["行不由徑", "走路不抄小路捷徑。比喻行事光明正大，不投機取巧。", "朱主任為人行不由徑，處事公正，受到同事的愛戴。"], ["文質彬彬", "原形容人既文雅又樸實，後形容人文雅有禮貌。", "這位主持人容貌出眾，談吐優雅，文質彬彬，吸引很多觀眾。"], ["風行草偃", "比喻在上位者以德化民。", "校長以身作則，實行「綠色生活」，於是風行草偃，全校師生一致努力踐行。"]]]]}, {"title": "三、相關作品欣賞　（一）十五志於學──也談「生涯規劃」　薛仁明", "page": "P.71-72", "blocks": [["text", "para", "志氣如詩。好的時代裡，年少之人，各有其志；而少年十五二十時，也人人皆可是詩人。詩主感，又主興；孔子說，「興於詩」。詩向來也講不明，說不清；現在學校教授古詩，為圖方便，硬是逐句翻譯成大白話：說是教學，其實是造孽。他們把學生僅剩的感悟能力，也將扼殺殆盡。"], ["text", "para", "詩，是透過文字，與天地精神相往來；詩，是通過文字，與人世風景相映照。詩是孔子說的「思無邪」，是日月光華照見天地萬物，歷然爽豁，俱生好意。詩是年少的志氣滿滿。          ；即便稍稍過當，即便恣縱無涯，都無礙於那厚實底氣。年少青春，有此深厚底氣，好比盤纏殷實，往後的人生，便可「走盡天涯，歌盡桃花」。"], ["text", "para", "「走盡天涯，歌盡桃花」，這般且吟且嘯、且歌且謠，完全迥異於今日所言的「生涯規劃」。「生涯規劃」之為惡，正在於完全沒有詩情。年少時代，無有詩情，何言青春？無有詩情，何言志氣？「生涯規劃」，是標準化社會的產物，明確清晰，像張工程圖；          ，成為一個標準產品。「生涯規劃」之人生，如生產線。此時此地，裝零件；彼時彼地，釘螺絲；傳送至末了，裝配完畢，但生命也成烏有。雖然即將烏有，這物化社會仍因利之所在，透過各種訊息，以不連累他人為名，勸你儘早再做個「規劃」，所謂「生前契約」。"], ["text", "para", "這條生產線上，人人依照相仿的「進度」，按部就班，循序漸進。通常，開頭是用功讀書，考好學校；不用功也行，總之找好工作，努力賺錢，設法理財；然後購車、買房、養保險，最後，再來個「生前契約」吧！如此這般，賺錢、退休、養老，如果人生只剩如此，真是不要也罷！休怪年輕人無感無興，也休怪年輕人不知志氣為何物。畢竟，除了這一份份的「生涯規劃」，我們成人世界，到底還能給她們什麼？又能教給他們什麼？"], ["text", "para", "孔子的時代，重重憂患；但他那時，滿滿志氣。          ，到了晚年，還動輒問對門人，「盍各言爾志？」千百年後，孔子若是地下有知，當仍願意召喚今日年少者：甩開那勞什子的「生涯規劃」吧！來吧！說說你的志向，老夫愛聽呢！"], ["text", "q", "【(C)】1.依據上文，下列何者符合作者對於「詩」的觀點？"], ["text", "opt", "(A)詩氣是文學的表現，與志向無關　　　(B)「興於詩」表示詩能夠撥亂興治"], ["text", "opt", "(C)詩化的語言，映照天地人世風景　　　(D)「思無邪」指詩使人易心生雜念"], ["text", "exp", "【解析】(A)由「志氣如詩」可知為非。(B)由「詩主感，又主興」可知作者主要強調詩要自己感悟，並未提及有撥亂興治的功能。撥亂興治：平定亂世，從事建設。(C)由「詩，是透過文字，與天地精神相往來；詩，是通過文字，與人世風景相映照」可知。(D)由「是日月光華照見天地萬物，歷然爽豁，俱生好意」可知為非。"], ["text", "q", "【(B)】2.若要將(甲)、(乙)、(丙)填入上文，使全文完整通順，則三處          內依序應填入："], ["text", "para", "(甲)他十五志於學，而後志於道"], ["text", "para", "(乙)青衿之志，貴在昂揚，貴在飽滿"], ["text", "para", "(丙)人但凡按部就班，就能達成「目的」"], ["text", "opt", "(A)(乙)(甲)(丙)　　　(B)(乙)(丙)(甲)　　　(C)(丙)(甲)(乙)　　　(D)(丙)(乙)(甲)"], ["text", "exp", "【解析】(B)由「詩是年少的志氣滿滿」、「即便稍稍過當，即便恣縱無涯」前後文意可知應接(乙)。而從「明確清晰，像張工程圖」、「成為一個標準產品」可知應接(丙)。又由「孔子的時代」、「但他那時，滿滿志氣」與「到了晚年，還動輒問對門人，『盍各言爾志？』」可知應接(甲)。"], ["text", "q", "【(D)】3.依據上文，下列敘述何者正確？"], ["text", "opt", "(A)作者認為年輕人要遵循常規擬定生涯規劃，完成目標"], ["text", "opt", "(B)作者提倡「生前契約」的觀念，可以保障人生的幸福"], ["text", "opt", "(C)「走盡天涯，歌盡桃花」就是如生產線的「生涯規劃」人生"], ["text", "opt", "(D)作者鼓勵年輕人要拋開制式觀念，胸懷詩情，才能懷抱壯志"], ["text", "exp", "【解析】(A)作者認為遵循常規的生涯規劃，賺錢、退休、養老，如果人生只剩如此，真是不要也罷。(B)由「這物化社會仍因利之所在，透過各種訊息，以不連累他人為名，勸你儘早再做個『規劃』，所謂『生前契約』」，可知作者未提倡「生前契約」的觀念。(C)「走盡天涯，歌盡桃花」是充滿詩情、詩志的人生。(D)由「千百年後，孔子若是地下有知，當仍願意召喚今日年少者：甩開那勞什子的『生涯規劃』吧！來吧！說說你的志向，老夫愛聽呢！」可知。"], ["text", "para", "【賞析】本文作者旨在論述詩言志，孔子曾說：「詩可以興。」由於「詩」乃出自於人的感情，這種感情的語言在反覆的抑揚吟詠之間，可進入人的內心深處，興發鼓舞人意志的作用。而詩也是孔子所說的「思無邪」，能讓人心無邪念、純正而合乎禮教。作者對於現今社會過於強調標準化的「生涯規劃」，提出獨特的看法，作者認為年輕人應拋開這種制式的觀念，要胸有詩情，才能懷抱壯志。"]], "layout": "split"}, {"title": "（二）自我克制：更多的快樂、創意與尊嚴 王溢嘉", "page": "P.73-74", "blocks": [["text", "para", "孔子是個很注重自我克制、自我約束的人，他說：「以約，失之者鮮矣。」（里仁）意思是能自我約束的人，犯的過錯就很少。但所謂克制或約束絕無禁止之意，而是要「約之以禮」（雍也）、「克己復禮」（顏淵），讓欲望和行為回復到（或符合）「禮」的儀軌上。當然，「非禮勿視，非禮勿聽，非禮勿言，非禮勿動」（顏淵）的幾個「勿」可能給人很大的束縛、壓迫感，但這其實是受到傳統解釋窠臼「束縛」的關係。"], ["text", "para", "當我們說「克制」時，針對的是不當、有害的欲望，但什麼是「不當」、「有害」？習慣的想法是指「過多」的欲望，其實，有些欲望「過少」（譬如厭食）也是有害的，這時就要克制自己想要成為「纖瘦美女」的想望，而「增加」自己的食欲。所以，我們要克制的其實是「過度」──過多或過少的欲望都屬不當。"], ["text", "q", "【(A)】1.文中首段畫線處說明孔子的為人，下列詞語何者符合對孔子的形容？"], ["text", "para", "(甲)束身自修　　(乙)頤指進退　　(丙)嚴以律己　　(丁)深文周納"], ["text", "opt", "(A)(甲)(丙)　　　　　(B)(乙)(丁)"], ["text", "opt", "(C)(甲)(乙)(丙)　　　　(D)(乙)(丙)(丁)"], ["text", "exp", "【解析】(A)由「注重自我克制、自我約束」可知(甲)、(丙)符合孔子之為人。(甲)約束自己、自我修養。(乙)用面部表情指揮人進退。比喻以高傲的態度指揮別人。(丙)以嚴格的態度來約束自己。(丁)指不根據事實，而巧妙的援引苛刻的法條，陷人入罪。"], ["text", "q", "【(A)】2.關於「以約，失之者鮮矣」的說明，下列何者理解不適當？"], ["text", "opt", "(A)「約」是約束、管束、克制、限制，具有完全禁止的意思"], ["text", "opt", "(B)依照「禮」來約束身心，讓欲望和行為符合「禮」的規範"], ["text", "opt", "(C)「非禮勿視」之「勿」給人束縛感，與傳統解釋窠臼有關"], ["text", "opt", "(D)一個能夠懂得約束自己的人，比較少會有犯下過錯的時候"], ["text", "exp", "【解析】(A)由「但所謂克制或約束絕無禁止之意」，可知並不是完全禁止的意思。(B)由「要『約之以禮』、『克己復禮』，讓欲望和行為回復到（或符合）『禮』的儀軌上」可知。(C)由「『非禮勿視，非禮勿聽，非禮勿言，非禮勿動』的幾個『勿』可能給人很大的束縛、壓迫感，但這其實是受到傳統解釋窠臼『束縛』的關係」可知。(D)由「能自我約束的人，犯的過錯就很少」可知。"], ["text", "q", "【(D)】3.下列何者最符合上文所述？"], ["text", "opt", "(A)「克制」，是針對人們內心產生的所有欲望而言"], ["text", "opt", "(B)「過多」的欲望有益人類的進步發展，無須克制"], ["text", "opt", "(C)「厭食」、「纖瘦美女」是正確的想望及行為表現"], ["text", "opt", "(D)「過度」指超越適當的限度，易損害自己的身體"], ["text", "exp", "【解析】(A)由「當我們說『克制』時，針對的是不當、有害的欲望」，可知不是針對人心裡產生的所有的欲望而言。(B)由「但什麼是『不當』、『有害』？習慣的想法是指『過多』的欲望」，可知作者認為「過多」的欲望，包含「不當」、「有害」的，需懂得克制。(C)由「有些欲望『過少』（譬如厭食）也是有害的、這時就要克制自己想要」，可知是有害自己的想望及行為表現。(D)由「我們要克制的其實是『過度』──過多或過少的欲望都屬不當」可知。"], ["text", "para", "【賞析】本文作者認為孔子是一位自我克制、嚴以律己的人，從論語中提及的「以約，失之者鮮矣」、「約之以禮」、「克己復禮」到「非禮勿視，非禮勿聽，非禮勿言，非禮勿動」，作者逐一剖析「克制」的深層意涵。「克制」絕無禁止的意思，「克制」乃是針對不當、有害的欲望而言，我們要克制的是「過度」，而過多或過少的欲望皆屬不當的行為。"]], "layout": "split"}, {"title": "伍 統測試題精選", "page": "P.74-76", "blocks": [["text","mj","伍　統測試題精選"],["text","q","【(A)】1.王同學將(甲)～(己)六部典籍，填入按「作者」、「經書子書」、「史書」分類的交叉查詢表，其中位置正確的典籍為何？ 【109統測】"],["text","html","<div class=\"hd-tw\"><table class=\"jy-table jy-cols-4 hd-table\" data-merged=\"1\"><tr><td rowspan=\"2\" colspan=\"2\"></td><th class=\"jy-th\" colspan=\"2\">作者</th></tr><tr><th class=\"jy-th\">集體作者</th><th class=\"jy-th\">單一具名作者</th></tr><tr><th class=\"jy-th\" rowspan=\"2\">經書子書</th><td>語錄體</td><td>(甲)論語</td><td>(乙)荀子</td></tr><tr><td>專題論述</td><td>(丙)孟子</td><td></td></tr><tr><th class=\"jy-th\" rowspan=\"2\">史書</th><td>編年體</td><td>(丁)戰國策</td><td></td></tr><tr><td>紀傳體</td><td>(戊)左傳</td><td>(己)史記</td></tr><tr><td colspan=\"4\" style=\"text-align:left\">註：「語錄體」是將對話紀錄直接呈現，「專題論述」為一篇論一主題，通常主題即是篇名。</td></tr></table></div>"],["text","opt","(A)(甲)(己)"],["text","opt","(B)(乙)(丙)(戊)"],["text","opt","(C)(甲)(丙)(丁)(己)"],["text","opt","(D)(乙)(丁)(戊)(己)"],["text","exp","【解析】(乙)荀子為專題論述；(丙)孟子為語錄體；(丁)戰國策為國別史體例；(戊)左傳為編年體著作。因此答案選(A)。"],["text","q","【(A)】2.下列選項，何者說明下文「在儒家價值體系中早有明確的分劃」？ <span class=\"jy-cir\">①</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">108　統測</span></span>"],["text","para","知識份子的立身處世之道，在儒家價值體系中早有明確的分劃，那就是兼善或獨善—將自己置身於政治漩渦之中，一伸治平之志；或蟬蛻於塵囂之中，自致於寰區之外，和政治保持某種程度的疏離。 （改寫自逯耀東　且做神州袖手人）"],["text","opt","(A)用之則行，舍之則藏"],["text","opt","(B)君子喻於義，小人喻於利"],["text","opt","(C)見賢思齊焉，見不賢而內自省也"],["text","opt","(D)政者，正也。子帥以正，孰敢不正"],["text","exp","【解析】題幹敘述強調「在儒家價值體系中早有明確的分劃」是「兼善或獨善」，則相應的答案為(A)。"],["text","trans","【語譯】(A)受到任用，就出來將治國平天下的大道推行於世；不被任用時，則沉潛努力充實自我，等待良機。論語　述而。(B)君子重視的是道義，而小人只知道利益。論語　里仁。(C)看見賢德之人就向他看齊，期許自己能像對方一樣好；看見不賢德之人，別急著批評指責，內心應先反省，衡量自己是否有像對方一樣的過錯？論語　里仁。(D)政治，就是端正之道。自己以身表率，用正直不偏私的方式來領導眾人，那麼誰還敢不行正道呢？論語　顏淵。"],["text","q","【(A)】3.下列甲、乙兩朵文字雲由兩本經典製成，書中使用次數越多的字，字體越大，則這兩本經典依序應是： <span class=\"jy-cir\">②</span><span class=\"jy-blank\" onclick=\"this.classList.toggle(&#39;show&#39;)\"><span class=\"jy-blank-ph\">&nbsp;&nbsp;&nbsp;&nbsp;</span><span class=\"jy-blank-ans\">107　統測</span></span>"],["text","para","<img src='img/侍坐/1dd77cf26ae06d42.png' style='max-width:100%;width:460px;display:block;margin:10px auto' alt=''>"],["text","opt","(A)論語／左傳"],["text","opt","(B)論語／荀子"],["text","opt","(C)孟子／左傳"],["text","opt","(D)孟子／荀子"],["text","exp","【解析】由甲圖出現「君子」、「小人」、「子路」、「孔子」等文字資料可知為論語；由乙圖出現「晉」、「公子」、「盟」、「鄭」、「寡君」、「使」、「師」等文字資料可推知為左傳。左傳記述春秋時發生的戰爭事件，如「晉　楚　城濮之戰」、「秦　晉　殽之戰」等。"]], "layout": "split"}], "charBian": [{"name": "以", "pages": [{"sub": "字義辨析", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"2\">義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">因為</th><td><b>以</b>吾一日長乎爾<span class=\"cb-loc\">（第一段，P.100）</span><br>毋吾<b>以</b>也<span class=\"cb-loc\">（第一段，P.100）</span></td></tr>\n<tr><th class=\"jy-th\">用</th><td>為國<b>以</b>禮<span class=\"cb-loc\">（第六段，P.103）</span><br>加之<b>以</b>師旅，因之<b>以</b>饑饉<span class=\"cb-loc\">（第二段，P.101）</span><br>如或知爾，則何<b>以</b>哉<span class=\"cb-loc\">（第一段，P.100–101）</span></td></tr>\n<tr><th class=\"jy-th\">則、就</th><td>如其禮樂，<b>以</b>俟君子<span class=\"cb-loc\">（第三段，P.102）</span></td></tr>\n</table>"}]}, {"name": "如", "pages": [{"sub": "字義辨析", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"2\">義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">如果</th><td><b>如</b>或知爾，則何以哉<span class=\"cb-loc\">（第一段，P.100–101）</span></td></tr>\n<tr><th class=\"jy-th\">或者</th><td>方六、七十，<b>如</b>五、六十<span class=\"cb-loc\">（第三段，P.101）</span><br>安見方六、七十，<b>如</b>五、六十，而非邦也者<span class=\"cb-loc\">（第六段，P.104）</span><br>宗廟之事，<b>如</b>會同<span class=\"cb-loc\">（第四段，P.102）</span></td></tr>\n<tr><th class=\"jy-th\">至於</th><td><b>如</b>其禮樂，以俟君子<span class=\"cb-loc\">（第三段，P.102）</span></td></tr>\n<tr><th class=\"jy-th\">何如（＝如何），怎麼樣</th><td>求，爾何<b>如</b><span class=\"cb-loc\">（第三段，P.101）</span><br>赤，爾何<b>如</b><span class=\"cb-loc\">（第四段，P.102）</span><br>點，爾何<b>如</b><span class=\"cb-loc\">（第五段，P.102）</span><br>夫三子者之言何<b>如</b><span class=\"cb-loc\">（第六段，P.103）</span></td></tr>\n</table>"}]}, {"name": "與", "pages": [{"sub": "義辨", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"3\">音 ｜ 義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>贊同、讚許</td><td>吾<b>與</b>點也<span class=\"cb-loc\">（第五段，P.103）</span></td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>支持、贊助</td><td>天道無親，常<b>與</b>善人（《老子》第七十九章）</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>親附</td><td>失其所<b>與</b>，不知（《左傳．燭之武退秦師》）</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>向、對</td><td><b>與</b>虎謀皮</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>通「舉」，推舉、選拔</td><td>選賢<b>與</b>能（《禮記．大同與小康》）</td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>等待</td><td>時不我<b>與</b></td></tr>\n<tr><th class=\"jy-th\">ㄩˇ</th><td>同類</td><td>民胞物<b>與</b></td></tr>\n<tr><th class=\"jy-th\">ㄩˊ</th><td>通「歟」，句末助詞，表達疑問、反詰、感嘆的語氣</td><td>唯求則非邦也<b>與</b><span class=\"cb-loc\">（第六段，P.104）</span><br>唯赤則非邦也<b>與</b><span class=\"cb-loc\">（第六段，P.104）</span></td></tr>\n<tr><th class=\"jy-th\">ㄩˋ</th><td>參加</td><td>參<b>與</b></td></tr>\n</table>"}]}, {"name": "舍", "pages": [{"sub": "形音義辨析", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"3\">音 ｜ 義 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">ㄕㄜˇ</th><td>放下</td><td>鼓瑟希，鏗爾，<b>舍</b>瑟而作<span class=\"cb-loc\">（第五段，P.102）</span></td></tr>\n<tr><th class=\"jy-th\">ㄕㄜˇ</th><td>停止、休息</td><td>逝者如斯夫！不<b>舍</b>晝夜（《論語．子罕》）<br>駑馬十駕，功在不<b>舍</b>（《荀子．勸學》）</td></tr>\n<tr><th class=\"jy-th\">ㄕㄜˋ</th><td>房屋</td><td>土地平曠，屋<b>舍</b>儼然（陶淵明〈桃花源記〉）</td></tr>\n<tr><th class=\"jy-th\">ㄕㄜˋ</th><td>三十里</td><td>退避三<b>舍</b></td></tr>\n</table>"}]}, {"name": "通同字", "pages": [{"sub": "通同字", "body": "<table class=\"jy-table\">\n<tr><th class=\"jy-th-full\" colspan=\"3\">字 ｜ 通 ｜ 例</th></tr>\n<tr><th class=\"jy-th\">希</th><td>通「稀」</td><td>鼓瑟<b>希</b><span class=\"cb-loc\">（第五段，P.102）</span></td></tr>\n<tr><th class=\"jy-th\">舍</th><td>通「捨」</td><td><b>舍</b>瑟而作<span class=\"cb-loc\">（第五段，P.102）</span></td></tr>\n<tr><th class=\"jy-th\">莫</th><td>「暮」的本字</td><td><b>莫</b>春者<span class=\"cb-loc\">（第五段，P.103）</span></td></tr>\n<tr><th class=\"jy-th\">與</th><td>通「歟」</td><td>唯求則非邦也<b>與</b><span class=\"cb-loc\">（第六段，P.104）</span><br>唯赤則非邦也<b>與</b><span class=\"cb-loc\">（第六段，P.104）</span></td></tr>\n</table>"}]}], "tGuide": {"v":"v4-20261110","afterLabel":"課後延伸·談志（六題）","nodes":[{"id":"op","seg":"第一段","at":2,"title":"開場｜理解「志」的提問情境","say":"孔子問：「如或知爾，則何以哉？」不是要弟子報告職業，而是假設有人任用他們，想知道各自願意承擔什麼事。","ask":"先請學生圈出四人回答中表示「承擔、能力、志向」的語句。","pts":"四人都在回答：若有機會參與政事，我想做什麼？","ref":"先建立共同情境，避免一開始就把四人貼上性格標籤。","avoid":"不要先把「志」縮成職業或官位。","q":"孔子問「如或知爾，則何以哉」，是在問什麼？","a":"如果有人了解你、願意任用你，你要怎麼做？"},{"id":"s1","seg":"第二段","at":0,"title":"子路｜國家處境","say":"先看子路想治理的國家。它不是普通的小地方，而是夾在大國之間，又遇到軍事侵擾與饑荒。","ask":"「攝乎大國之間」寫出什麼處境？「師旅」「饑饉」各屬哪一類問題？","pts":"外患：受大國壓迫、軍事侵擾；內憂：饑荒。整體是內憂外患。","ref":"依課本註釋解釋「攝」「師旅」「饑饉」即可，不必讓學生反覆逐字翻譯。","avoid":"「師旅」依課本譯作外敵侵略；不要擴寫成具體戰爭情節。","q":"子路的國家遇到什麼困難？","a":"夾在大國之間，又有戰爭、饑荒：內憂外患。"},{"id":"s2","seg":"第二段","at":1,"title":"子路｜治理目標","say":"子路接著說「由也為之」，表示願意承擔；他希望三年後使人民「有勇，且知方」。","ask":"「有勇」和「知方」分別指什麼？「比及三年」透露他對自己有什麼信心？","pts":"使人民有勇氣，也懂得禮義；子路對三年內達成目標很有信心。","ref":"「方」依課本註為禮義；勇而無義可能流於作亂，可補充《論語．陽貨》「君子有勇而無義為亂」。","avoid":"不要把「有勇」直接等同軍隊強大，也不要把「知方」只解成服從命令。","q":"子路想在三年內做到什麼？","a":"使人民有勇氣，也懂得禮義（知方）。"},{"id":"s3","seg":"第二段","at":2,"title":"子路｜孔子「哂之」","say":"讀到「夫子哂之」，先不急著公布原因。讓學生注意子路回答前的「率爾而對」，以及孔子當下的反應。","ask":"「哂」是什麼表情？「率爾而對」透露什麼？你猜孔子笑的是能力，還是回答方式？","pts":"哂：微笑。率爾：輕率、搶先。先留下猜測，等第六段再驗證。","ref":"將「搶先回答」與「個性直率」分開：前者是文本動作，後者只是可能的性格推論。","avoid":"不要直接說孔子嘲笑子路，也不要先判定子路自大。","q":"孔子為什麼「哂」子路？先猜猜。","a":"先記下你的猜測，第六段孔子會自己說。"},{"id":"s4","seg":"第三段","at":1,"title":"冉有｜治理規模與目標","say":"冉有談的地方比子路的小。他沒有說自己要治理千乘之國，而是方六、七十里，或五、六十里的小國。","ask":"和子路相比，治理規模有何不同？冉有希望三年後做到什麼？","pts":"規模較小；目標是「足民」，使人民富足。","ref":"「如」依課本註解作「或者」；先做客觀比較，不預設他刻意把國家說小。","avoid":"不要從國家規模較小，推論冉有能力較差。","q":"冉有和子路，哪裡不同？","a":"治理的國家較小；目標是使人民富足。"},{"id":"s5","seg":"第三段","at":2,"title":"冉有｜把禮樂交給君子","say":"冉有說自己可以使人民富足；至於禮樂，則「以俟君子」。這是他對自己能力範圍的表述。","ask":"他願意承擔什麼？又把什麼交給君子？這反映怎樣的自我定位？","pts":"能使人民富足；禮樂教化則等待君子推行。可以看出他有所保留、謙退。","ref":"朱熹解作「冉有謙退，又以子路見哂，故其辭益遜」；這是朱熹的解讀，不是原文直接交代的心理活動。<br>（舊版補充）冉有曾問孔子人民多了、富了以後還要做什麼，孔子答「富之」再「教之」（〈子路〉）——冉有只承擔「富」這一步。","avoid":"不要說冉有「嚇到裝弱」或「沒有自信」；宜說謙退、自我限定。","q":"禮樂，冉有交給誰？","a":"交給君子推行；他自己負責使人民富足。"},{"id":"s6","seg":"第四段","at":1,"title":"公西華｜願學","say":"公西華先說「非曰能之，願學焉」，不宣稱自己已經能勝任，而是表示願意學習。","ask":"他接下來想參與的是哪一類事務？","pts":"宗廟祭祀、諸侯會同等國家禮儀活動。","ref":"宗廟之事指祭祀祖先；會同涉及諸侯朝覲、會盟。讓學生看見他談的是禮儀專業。<br>（舊版補充）冉有剛把禮樂留給君子，公西華接著談的正是禮樂之事——他不說自己能勝任，只說願意學。","avoid":"不要把「願學」說成完全沒有能力；他是在謙遜表達。","q":"「非曰能之，願學焉」是什麼態度？","a":"不說自己已經能做到，而是說願意學習。"},{"id":"s7","seg":"第四段","at":2,"title":"公西華｜小相","say":"公西華希望穿戴禮服、禮冠，在典禮中擔任小相。這裡的「相」是協助引導、贊禮的角色。","ask":"小相在典禮中做什麼？「小」是能力不足，還是職位上的謙稱？","pts":"協助典禮、引導禮節；「小」帶有謙稱意味。","ref":"可用現代國家典禮的禮賓官作比喻；「大」與「小」是禮儀職務層次的比較，不是總統與副總統，也不是正副宰相。","avoid":"不要把大相、小相套成宰相制度；也不要把小相說成只負責遞文件的打雜人員。","q":"公西華想做什麼？","a":"在宗廟祭祀、諸侯會同的典禮中擔任小相（協助引導、贊禮）。"},{"id":"s8","seg":"第四段","at":"sum","title":"前三人統整｜志向與表達方式","say":"前三人都回答「如果被任用，我能為國家做什麼」，但承擔的內容與表達方式不同。","ask":"各用一句話概括三人的志向，再比較他們如何表達自己的能力。","pts":"子路：使民有勇、知方；冉有：使民富足；公西華：學習並參與國家禮儀。子路直接承擔，冉有限定範圍，公西華表示願學並自謙。","ref":"先讓學生依原句比較，不急著貼上「自信、沒自信、高情商」等固定性格標籤。","avoid":"不要將三人排成「一個比一個謙讓」的單一路線。","q":"三人怎麼說自己的能力？","a":"子路直接承擔（由也為之）；冉有限定範圍（求也為之、以俟君子）；公西華說願學、自稱小相。"},{"id":"s9","seg":"第五段","at":1,"title":"曾皙｜回答前的動作","say":"曾皙原本正在鼓瑟，聽到孔子提問後，瑟聲漸弱，接著放下瑟、起身回答。","ask":"把「率爾而對」和「舍瑟而作」放在一起看，兩人的回答姿態有何不同？","pts":"子路搶先回答；曾皙停下演奏、放下樂器、起身再答。可由動作推論曾皙較從容、有禮。","ref":"「從容有禮」是根據動作作出的推論，不是課文明說的人格評語。","avoid":"不要把曾皙說成因為心境最穩，所以看清所有人的心理。","q":"曾皙和子路，回答前的動作哪裡不同？","a":"子路搶先回答；曾皙停下彈瑟、放下瑟、起身才回答。"},{"id":"s10","seg":"第五段","at":2,"title":"曾皙｜先表明不同","say":"曾皙先說「異乎三子者之撰」，表示自己想說的和前三人不同。孔子回答「何傷乎？亦各言其志也」，鼓勵他不必顧慮。","ask":"前三人談什麼？曾皙為何先提醒自己不同？孔子的回應帶來什麼效果？","pts":"前三人談受任後如何治理；曾皙要談另一種志向。孔子表示每個人都可以說自己的志向。","ref":"「撰」依課本註作「陳述」；另有注家解作「具、才能」，不同說法留在教師補充即可。","avoid":"不要把注家異說變成學生必背知識。","q":"曾皙說「異乎三子者之撰」，孔子怎麼回應？","a":"「何傷乎？亦各言其志也」：說說無妨，本來就是各說各的志向。"},{"id":"s11","seg":"第五段","at":3,"title":"曾皙｜生活圖景","say":"曾皙描繪暮春時節，成年人與少年穿著春衣，到沂水、舞雩一帶活動，最後唱著歌回家。","ask":"畫面裡有哪些人、做了什麼？整體呈現怎樣的生活氛圍？","pts":"不同年齡的人一起親近自然、自在活動；畫面安定、和樂、從容。","ref":"「浴乎沂」「風乎舞雩」「詠而歸」要依課文與課本註解理解；「浴」不必硬說成現代海邊游泳。","avoid":"不要加上海灘、烤肉、開車、YouTuber 等原文沒有的情節。","q":"曾皙描繪的是什麼畫面？","a":"暮春時節，大人和孩子一起到沂水邊洗浴、在舞雩臺上乘涼，唱著歌回家。"},{"id":"s12","seg":"第五段","at":3,"title":"曾皙｜這為什麼也是「志」","say":"曾皙沒有提出行政措施，卻描繪自己嚮往的生活。志向不一定只能是官職或治理方案，也可以是想過的生活。","ask":"這樣的生活需要哪些條件？若社會長期動盪，這幅圖景容易實現嗎？","pts":"需要安定的環境與群體和諧；戰亂中不容易實現。","ref":"課本段析可將它理解為禮樂治理下太平社會的縮影；但「曾皙直接提出完整政治方案」並非原文。","avoid":"不要把「曾皙只想自己享樂」或「他已提出完整治國方案」當成定論。","q":"曾皙沒有談治國，為什麼也算「志」？","a":"他說的是自己嚮往的生活；志向也可以是想過的生活，不一定是官職。"},{"id":"s13","seg":"第五段","at":4,"title":"孔子｜吾與點也","say":"孔子聽完後「喟然嘆」，接著說「吾與點也」。先確定「與」是贊同，再討論嘆息可能包含的情感。","ask":"孔子為何贊同曾皙？這聲嘆息還可能包含什麼？請提出文本或生平依據。","pts":"課本賞析：寄寓對禮樂教化、清平盛世的期待；嘆息是否另含嚮往或感慨，可作有根據的延伸推論。","ref":"「對禮樂教化、清平盛世的期待」是課本主要詮釋；「理想難以實現的感慨」屬延伸推論，不要說成原文明示。","avoid":"不要把孔子贊同曾皙簡化成「只想大家去郊遊」或「前三人都錯了」。","q":"孔子為什麼說「吾與點也」？","a":"贊同曾皙；寄寓對禮樂教化、清平盛世的期待（課本賞析）。"},{"id":"s14","seg":"第六段","at":4,"title":"第六段｜回看子路","say":"曾皙追問孔子為何哂子路，孔子親自回答：「為國以禮，其言不讓，是故哂之。」","ask":"孔子指出子路哪裡不合宜？他否定的是能力，還是說話態度？<br>（舊版開放題，可選用）如果你是國君，會任用子路嗎？為什麼？","pts":"治國要合乎禮；子路說話沒有謙讓。孔子批評的是態度，不是否定其治理能力。","ref":"朱熹說「夫子蓋許其能，特哂其不遜」；可用來補充孔子對子路能力的肯定。<br>（舊版補充）曾皙先問三子之言何如，孔子只說「亦各言其志也已矣」，沒有當場判誰對誰錯。","avoid":"不要把哂解成惡意嘲笑，也不要說子路只是吹牛。","q":"孔子笑子路，笑的是什麼？","a":"「為國以禮，其言不讓」：笑他說話不謙讓，不是否定他的能力。"},{"id":"s15","seg":"第六段","at":8,"title":"第六段｜回看冉有、公西華","say":"孔子接著說，方圓數十里的地方仍然是國家；宗廟、會同也是諸侯的大事。","ask":"孔子為何替冉有、公西華補充說明？這是否表示前三人被曾皙比下去？","pts":"小國仍是國家，治理小國也是治國；宗廟會同是國家大事。孔子沒有否定冉有、公西華的志向。","ref":"「唯求／唯赤則非邦也與」的問答者，朱熹與皇侃、邢昺等注疏有不同判斷；教師知道即可，不必要求學生背誦。","avoid":"不要說孔子只認同曾皙、完全否定前三人。","q":"孔子否定冉有、公西華了嗎？","a":"沒有：小國也是國家；宗廟會同也是諸侯大事，「小相」只是謙稱。"},{"id":"s16","seg":"第六段","at":"box","title":"全課收束｜四種志向、四種出發點","say":"回到開頭的問題：如果有人願意任用你，你想做什麼？四位弟子沒有交出同一種答案。<br>其實四個人的回答，分別代表四種不同的思考出發點：<br>① 子路：我有能力解決什麼問題？<br>② 冉有：我能負責到什麼程度？<br>③ 公西華：我希望在哪個專業領域貢獻自己？<br>④ 曾皙：我理想中的生活究竟是什麼樣子？","ask":"請用關鍵詞整理四人，再想想：一個人一定要有政治抱負、職業成就，才算有志向嗎？想過一種自己認同的生活，算不算志？","pts":"子路：使民有勇、知方；冉有：使民足；公西華：願學禮儀；曾皙：嚮往和樂生活。志也可以是想過的生活。","ref":"「四種出發點」是教學上的歸納（老師 11/10 補充），不是課文原話；比把四人對應成四個現代官職更有教育意義。可以直接接到課後延伸「談志」。如時間足夠，再連結學生自己的選擇；不必把「內聖外王」當成本文原有架構。","avoid":"「內聖外王」是後世概括儒家理想的概念，不是本篇原文用語。不要把四人硬對應成現代官職。","q":"如果有人願意重用你——四個人各從什麼地方想起？","a":"子路：我有能力解決什麼問題？<br>冉有：我能負責到什麼程度？<br>公西華：我想在哪個領域貢獻自己？<br>曾皙：我理想中的生活是什麼樣子？"}],"after":[{"id":"a1","seg":"","at":"","title":"① 志是什麼？","say":"先從學生小時候的願望談起，再比較現在的想法。","ask":"小時候想做什麼？現在有沒有改變？為什麼？","pts":"志可以是目標、想成為的人，也可以是想過的生活；它會隨經驗與成長調整。","ref":"","avoid":"不要急著要求學生提出宏大的志向。","q":"小時候想做的事，和現在想的一樣嗎？「志」可以是什麼？","a":"志可以是目標、想成為的人，也可以是想過的生活；會隨經驗改變。"},{"id":"a2","seg":"","at":"","title":"② 還不知道志向，算沒有志嗎？","say":"把「不知道要什麼」和「什麼都不要」分開。","ask":"不知道，是還沒找到、還在嘗試，還是真的沒有想追求的事？","pts":"暫時說不出方向，不等於沒有志；也可能仍在探索。","ref":"","avoid":"不要把「不知道」視為懶惰或沒有理想。","q":"「不知道自己要什麼」和「什麼都不要」一樣嗎？","a":"不一樣。可能只是還沒找到方向，仍在探索。"},{"id":"a3","seg":"","at":"","title":"③ 小確幸算不算志？","say":"請學生回想一個最近覺得日子很好的畫面，再想像能否長久如此。","ask":"如果每天都能這樣生活，算不算一種志？需要哪些條件？","pts":"想過的生活也可以是志；它通常需要工作、時間、健康、人際關係與社會安定等條件。","ref":"","avoid":"連回曾皙時，不能直接斷定他只想個人享樂，或已提出完整政治方案。","q":"每天都能過著讓自己覺得「真好」的生活，算一種志嗎？","a":"算。想過的生活也可以是志，但需要一些現實條件支持。"},{"id":"a4","seg":"","at":"","title":"④「我只想打電動」","say":"先不判斷對錯，從學生玩遊戲時最有感的時刻切入。","ask":"最喜歡的是遊戲本身，還是成就感、挑戰、合作、創造、陪伴等感受？生活中還有哪裡能得到同樣感受？","pts":"興趣背後常有更深的需求；看見需求，可以找到遊戲以外的投入方向。","ref":"","avoid":"「每天打電動」不必立刻被否定；引導學生辨認喜歡的原因即可。","q":"你喜歡打電動的哪個部分？生活中還有什麼也能帶給你同樣感受？","a":"可能是挑戰、成就、合作、創造或陪伴；這些感受也能在其他活動中找到。"},{"id":"a5","seg":"","at":"","title":"⑤ 興趣從哪裡來？","say":"讓學生回想一項興趣的起點，看看它是天生喜歡，還是嘗試後才喜歡。","ask":"有沒有原本不熟、做過一陣子才發現有趣的事？","pts":"興趣可能經由接觸、嘗試、獲得成就感、持續投入而形成；每個人的路徑不同。","ref":"","avoid":"不要把「先找到興趣」和「先嘗試才有興趣」設成二選一。","q":"興趣一定是一開始就有的嗎？","a":"不一定。可能先接觸、嘗試，才發現有趣並願意持續投入。"},{"id":"a6","seg":"","at":"","title":"⑥ 我目前的方向","say":"讓學生從四位弟子的回答中選一個最有共鳴的，再寫出自己的「現在版本」。","ask":"你比較認同哪一種表達方式？如果孔子現在問你「如或知爾，則何以哉」，你會怎麼回答？","pts":"志向不必一次決定一生；能說出現在想往哪裡走，或願意先嘗試什麼，就已經是開始。","ref":"","avoid":"行動型、務實型、學習型、理想型只是理解志向表達的輔助，不是人格測驗。","q":"如果孔子現在問你：「如或知爾，則何以哉？」你會怎麼回答？","a":"可以寫：我想＿＿＿；我對＿＿＿有興趣但還不確定；我願意先試試＿＿＿。"}]}}]);
